/* ============ SALAMA WMS – vues : distribution 2027, dernier kilomètre, traçabilité, paramétrage ============ */
const destOpts=()=>Object.entries(REF.routes).map(([r,n])=>`<optgroup label="${r} – ${esc(n)}">${DEST.filter(d=>d.route===r).map(d=>`<option value="${d.code}">${esc(d.nom)} (${d.sp}, arrêt ${d.ordre})</option>`).join('')}</optgroup>`).join('');

/* ---------------- Commandes et validation DVM / DAS ---------------- */
let cmdF={cy:'C1',st:''};
VIEWS.commandes=()=>{const rows=S.orders.filter(o=>(!cmdF.cy||o.cycle===cmdF.cy)&&(!cmdF.st||o.statut===cmdF.st));
  return ph('Commandes et validation DVM / DAS','Une commande unique suit le besoin, la validation, la préparation, le transport, la POD, la facture et la clôture. Poids, volume et nombre de colis sont calculés dès la saisie à partir du catalogue (DEM-004), donc connus à la validation, avant J-20.',`<button class="btn p" data-x="ordNew">Nouvelle commande</button><button class="btn" data-x="xlsOrd">Exporter (Excel)</button>`)+
  `<div class="card"><div class="fx"><label>Cycle<select id="cCy"><option value="">Tous</option>${opt(REF.cycles.map(c=>c.c),cmdF.cy)}</select></label><label>Statut<select id="cSt"><option value="">Tous</option>${opt(FLOW,cmdF.st)}</select></label></div></div>`+
  table([{t:'Commande',f:o=>`<b class="mono">${o.no}</b><br><span class="small muted">${o.x3} · v${o.ver}</span>`},{t:'Destination',f:o=>`${esc(o.destNom)}<br><span class="small muted">${o.sp} · ${esc(REF.routes[o.route])}</span>`},{t:'Prio.',f:o=>pill(o.prio,o.prio==='P1'?'bad':o.prio==='P2'?'warn':'neu')},{t:'Lignes',r:1,f:o=>o.lignes.length},{t:'Colis',r:1,f:o=>fmt(o.calc.colis)},{t:'Poids kg',r:1,f:o=>fmt(o.calc.kg)},{t:'Volume m³',r:1,f:o=>fmt(o.calc.m3,2)},{t:'Statut',f:o=>ordPill(o.statut)},{t:'',f:o=>`<div class="row"><button class="btn s" data-x="ordView" data-a="${o.no}">Détail</button>${o.statut==='Brouillon'?`<button class="btn s o" data-x="ordSubmit" data-a="${o.no}">Soumettre</button>`:''}${o.statut==='Soumise'?`<button class="btn s p" data-x="ordVal" data-a="${o.no}">Valider</button>`:''}</div>`}],rows,{empty:'Aucune commande pour ce filtre.'})};
BIND.commandes=()=>{$('#cCy').onchange=e=>{cmdF.cy=e.target.value;refresh()};$('#cSt').onchange=e=>{cmdF.st=e.target.value;refresh()}};
ACT.xlsOrd=()=>xlsxExport('SALAMA_WMS_Commandes_'+iso(today()),[['Commandes',S.orders.map(o=>({Commande:o.no,X3:o.x3,Destination:o.destNom,'Sous-parcours':o.sp,Route:o.route,Cycle:o.cycle,Priorité:o.prio,Statut:o.statut,Colis:o.calc.colis,'Poids kg':+o.calc.kg.toFixed(1),'Volume m3':+o.calc.m3.toFixed(3),Version:o.ver}))],['Lignes',S.orders.flatMap(o=>o.lignes.map(l=>({Commande:o.no,Article:l.art,Désignation:ART[l.art]?.des,'Qté UD':l.qty})))]]);
function colisHTML(c){return `<div class="grid g2"><div>${table([{t:'Article',f:d=>esc(ART[d.art].des)},{t:'Qté UD',r:1,f:d=>fmt(d.qty)},{t:'UD / carton',r:1,f:d=>fmt(d.udc)},{t:'Cartons d’origine',r:1,f:d=>fmt(d.full)},{t:'UD en vrac',r:1,f:d=>d.rem?pill(fmt(d.rem),'warn'):'0'}],c.detail)}</div>
  <div>${table([{t:'Type de colis',f:r=>r.carton?`Carton de reconditionnement ${r.carton} <span class="small muted">(${r.tr} · ${r.temp})</span>`:'Cartons d’origine'},{t:'Nombre',r:1,f:r=>fmt(r.n)},{t:'kg',r:1,f:r=>fmt(r.kg,1)},{t:'m³',r:1,f:r=>fmt(r.m3,3)}],[{n:sum(c.orig,x=>x.n),kg:sum(c.orig,x=>x.kg),m3:sum(c.orig,x=>x.m3)}].concat(c.recon))}
  <div class="kpis" style="margin-top:8px"><div class="kpi k-info"><b>${fmt(c.colis)}</b><span>colis</span></div><div class="kpi k-info"><b>${fmt(c.kg)}</b><span>kg</span></div><div class="kpi k-info"><b>${fmt(c.m3,2)}</b><span>m³ (CBM)</span></div></div></div></div>
  <p class="small muted">Livraison à la plus petite unité de distribution : les cartons d’origine complets partent intacts ; le reliquat est prélevé à l’unité (vrac) et reconditionné en cartons standard 001 (25×21×12 cm), 003 (36×32×26 cm) ou 007 (54×40×35 cm), sans mélanger froid, stupéfiants et produits dangereux.</p>`}
ACT.ordView=no=>{const o=S.orders.find(x=>x.no===no);
  modal('Commande '+no,`${flowHTML(o.statut)}<div class="fx"><div class="fl">Destination<b>${esc(o.destNom)}</b></div><div class="fl">Sous-parcours<b>${o.sp} – ${esc(SP.find(s=>s.code===o.sp)?.nom)}</b></div><div class="fl">Priorité<b>${o.prio} – ${REF.prio[o.prio]}</b></div><div class="fl">Cycle<b>${o.cycle}</b></div><div class="fl">Saisie par<b>${esc(o.creePar)}</b></div><div class="fl">Validée par<b>${esc(o.validePar||'—')}</b></div><div class="fl">Mission<b>${esc(o.mission||'—')}</b></div><div class="fl">POD<b>${o.pod?`<a href="#pod" class="pill ok">POD ✓ ${o.pod}</a>`:'—'}</b></div></div>
  <h3>Lignes, disponibilité FEFO et colisage</h3>`+table([{t:'Article',f:l=>artLabel(l.art)},{t:'Qté UD',r:1,f:l=>fmt(l.qty)},{t:'Disponible FEFO (S1)',r:1,f:l=>{const d=dispo(l.art,'S1');return d>=l.qty?fmt(d):pill(fmt(d)+' – rupture partielle','bad')}},{t:'1er lot FEFO',f:l=>{const f=fefoLots(l.art,'S1')[0];return f?esc(lotOf(f.lotId).lot)+' · '+expPill(lotOf(f.lotId).exp):'—'}},{t:'Valeur MGA',r:1,f:l=>fmt(l.qty*ART[l.art].prix)}],o.lignes)+colisHTML(o.calc)+
  (o.hist&&o.hist.length?`<h3>Historique</h3>${table([{t:'Date',f:h=>frt(h.ts)},{t:'Par',k:'by'},{t:'Action',k:'a'},{t:'Commentaire',k:'c'}],o.hist)}`:''),
  (o.statut==='Livrée'?`<button class="btn n" data-x="ordClose" data-a="${no}">Clôturer (contrôle FIN-004)</button>`:'')+(['Validée','Soumise','Brouillon'].includes(o.statut)?`<button class="btn" data-x="ordEdit" data-a="${no}">Modifier (nouvelle version)</button>`:''),{w:'1150px'})};
ACT.ordNew=(no)=>{if(!need('ord'))return;const o=no?S.orders.find(x=>x.no===no):null;
  modal(o?'Modifier '+no+' (version '+(o.ver+1)+')':'Nouvelle commande',`<div class="fx"><label>Destination (114 arrêts du plan 2027)<select id="oD">${destOpts()}</select></label><label>Priorité<select id="oP">${opt(Object.entries(REF.prio).map(([k,v])=>[k,k+' – '+v]),o?.prio||'P4')}</select></label><label>Cycle<select id="oC">${opt(REF.cycles.map(c=>c.c),o?.cycle||'C1')}</select></label><label>Référence X3 (SOH)<input id="oX" value="${esc(o?.x3||'SOH-27-'+(1200+S.orders.length))}"></label></div>
  <h3>Lignes (quantités en unités de distribution)</h3><div id="oLines"></div><button class="btn s" id="oAdd">+ Ajouter une ligne</button><div id="oCalc"></div>`,
  `<button class="btn" data-x="ordSave" data-a="${no||''}" data-b="Brouillon">Enregistrer le brouillon</button><button class="btn o" data-x="ordSave" data-a="${no||''}" data-b="Soumise">Soumettre à validation</button>`,{w:'1150px'});
  if(o)$('#oD').value=o.dest;
  const lines=o?o.lignes.map(l=>({...l})):[{art:'PARA500',qty:60},{art:'SRO',qty:2500}];
  const draw=()=>{$('#oLines').innerHTML=lines.map((l,i)=>`<div class="row" style="margin-bottom:6px"><select data-i="${i}" class="oA" style="min-width:280px">${opt(S.articles.map(a=>[a.code,a.des+' – '+a.ud]),l.art)}</select><input type="number" min="1" class="oQ" data-i="${i}" value="${l.qty}" style="width:110px"><span class="small muted">dispo FEFO S1 : ${fmt(dispo(l.art,'S1'))} · ${fmt(ART[l.art].udc)} UD/carton</span><button class="btn s d" data-i="${i}" aria-label="Supprimer la ligne">×</button></div>`).join('');
    $$('.oA').forEach(s=>s.onchange=e=>{lines[+e.target.dataset.i].art=e.target.value;draw()});$$('.oQ').forEach(s=>s.oninput=e=>{lines[+e.target.dataset.i].qty=+e.target.value;calc()});$$('#oLines .btn.d').forEach(b=>b.onclick=e=>{lines.splice(+b.dataset.i,1);draw()});calc()};
  const calc=()=>{const c=colisage(lines);const d=DEST.find(x=>x.code===$('#oD').value);const sp=SP.find(s=>s.code===d.sp);const v=choixVehicule(c.m3,c.kg,sp);
    $('#oCalc').innerHTML=`<h3>Calcul automatique dès la saisie</h3>`+colisHTML(c)+`<div class="note">Sous-parcours ${d.sp} (${esc(sp.nom)}) · véhicule recommandé par le plan : <b>${esc(sp.veh)}</b> · seule, cette commande remplirait ${v.n} × ${esc(v.lib)} à ${pct(v.fill)} : le regroupement par sous-parcours se fait dans le plan de distribution.</div>`;ACT._lines=lines};
  $('#oAdd').onclick=()=>{lines.push({art:S.articles[0].code,qty:1});draw()};$('#oD').onchange=calc;draw()};
ACT.ordEdit=no=>{closeModal();ACT.ordNew(no)};
ACT.ordSave=(no,st)=>{const lines=(ACT._lines||[]).filter(l=>l.qty>0);if(!lines.length)return toast('Ajoutez au moins une ligne.',true);
  const dup=new Set();for(const l of lines){if(dup.has(l.art))return toast('Article en double : regroupez les quantités (DEM-003).',true);dup.add(l.art)}
  const d=DEST.find(x=>x.code===$('#oD').value);let o=no?S.orders.find(x=>x.no===no):null;
  if(o){o.ver++;o.statut=st;o.validePar='';o.hist.push({ts:Date.now(),by:me().nom,a:'Nouvelle version v'+o.ver,c:'Modification après saisie : nouvelle validation requise (VAL-005)'})}
  else{o={no:nextNo('cmd','CMD-'),ver:1,hist:[],creePar:me().nom,creeId:me().id,date:iso(today())};S.orders.unshift(o)}
  Object.assign(o,{x3:$('#oX').value,dest:d.code,destNom:d.nom,sp:d.sp,route:d.route,cycle:$('#oC').value,prio:$('#oP').value,lignes:lines.map(l=>({...l})),statut:st,creeId:o.creeId||me().id});o.calc=colisage(o.lignes);
  o.hist.push({ts:Date.now(),by:me().nom,a:st==='Soumise'?'Soumission':'Brouillon',c:''});audit('Commande',o.no,st+' v'+o.ver);closeModal();toast('Commande '+o.no+' : '+st);refresh()};
ACT.ordSubmit=no=>{if(!need('ord'))return;const o=S.orders.find(x=>x.no===no);o.statut='Soumise';o.hist.push({ts:Date.now(),by:me().nom,a:'Soumission',c:''});audit('Commande',no,'Soumise');refresh()};
ACT.ordVal=no=>{if(!need('ord_ok'))return;const o=S.orders.find(x=>x.no===no);
  if(o.creeId===me().id||o.creePar===me().nom)return toast('Séparation des tâches : vous avez saisi cette commande, un autre validateur doit la valider (VAL-004).',true);
  const short=o.lignes.filter(l=>dispo(l.art,'S1')<l.qty);
  modal('Validation DVM / DAS – '+no,`<p>${esc(o.destNom)} · ${o.sp} · ${o.prio} · ${fmt(o.calc.colis)} colis · ${fmt(o.calc.kg)} kg · ${fmt(o.calc.m3,2)} m³ · valeur ${fmt(sum(o.lignes,l=>l.qty*ART[l.art].prix))} MGA</p>${short.length?`<div class="note b">Rupture partielle sur ${short.length} article(s) : ${short.map(l=>esc(ART[l.art].des)).join(', ')}. La validation créera un reste à livrer pour la différence.</div>`:'<div class="note g">Stock libéré suffisant sur toutes les lignes, en respectant la durée résiduelle minimale.</div>'}
  <label class="fl">Commentaire (obligatoire en cas de rejet ou de retour)<textarea id="vCom"></textarea></label>`,
  `<button class="btn d" data-x="ordDec" data-a="${no}" data-b="Rejetée">Rejeter</button><button class="btn" data-x="ordDec" data-a="${no}" data-b="Brouillon">Retour pour correction</button><button class="btn p" data-x="ordDec" data-a="${no}" data-b="Validée">Valider et geler la version</button>`)};
ACT.ordDec=(no,st)=>{const o=S.orders.find(x=>x.no===no);const c=$('#vCom').value.trim();if(st!=='Validée'&&!c)return toast('Motif obligatoire (VAL-003).',true);
  o.statut=st;if(st==='Validée'){o.validePar=me().nom;o.gel=Date.now();x3('Commande client validée (SOH)','Commande client',o.x3,{version:o.ver,statut:'Validée'})}
  o.hist.push({ts:Date.now(),by:me().nom,a:st==='Validée'?'Validation (gel v'+o.ver+')':st==='Rejetée'?'Rejet':'Retour pour correction',c});audit('Validation commande',no,st);closeModal();toast('Commande '+no+' : '+st);refresh()};
ACT.ordClose=no=>{const o=S.orders.find(x=>x.no===no);const ral=S.ral.filter(r=>r.order===no&&r.statut==='Ouvert');const fact=S.x3msg.find(m=>m.ref===o.pod&&m.statut==='Accusé');
  const miss=[];if(!o.pod)miss.push('POD absente');if(ral.length)miss.push(ral.length+' reste(s) à livrer ouvert(s)');if(!fact&&!o.podDemo)miss.push('facture X3 non acquittée');
  if(miss.length&&!(o.pod&&S.pods.find(p=>p.no===o.pod)?.source==='Démonstration'))return toast('Clôture refusée : '+miss.join(', ')+' (FIN-004).',true);
  o.statut='Clôturée';o.hist.push({ts:Date.now(),by:me().nom,a:'Clôture',c:'Quantités, lots, POD, facture et paiement réconciliés'});audit('Commande',no,'Clôturée');closeModal();refresh()};

/* ---------------- Plan de distribution 2027 ---------------- */
let planCy='C1',planAll=false;
function planRows(cy){const ords=S.orders.filter(o=>o.cycle===cy&&['Validée','Planifiée','En préparation','Contrôlée','Emballée','En transit','Livrée','Clôturée'].includes(o.statut));
  const g=by(ords,'sp');return SP.filter(s=>planAll||g[s.code]).map(s=>{const os=g[s.code]||[];const m3=sum(os,o=>o.calc.m3),kg=sum(os,o=>o.calc.kg),colis=sum(os,o=>o.calc.colis);const v=os.length?choixVehicule(m3,kg,s):null;const ms=S.missions.find(m=>m.cycle===cy&&m.sp===s.code);return {s,os,m3,kg,colis,v,ms}})}
VIEWS.plan=()=>{const cy=REF.cycles.find(c=>c.c===planCy);const dep=new Date(cy.dep);const rows=planRows(planCy);
  const J=[['J-20','Réservation des camions internes, bon d’appel 3PL',jalon(dep,20)],['J-15','Stop / go : commande gelée, volume confirmé, équipe, camion',jalon(dep,15)],['J-14 → J-3','Préparation nivelée (10 jours ouvrés)',jalon(dep,14)],['J-3','Go / no-go final et contrôle départ',jalon(dep,3)],['J','Premier départ',dep],['J+7','POD transmise au plus tard',addD(dep,7)]];
  return ph('Plan de distribution cyclique 2027',`Méthode 2027 : 10 routes fixes, 44 sous-parcours, 4 cycles. La préparation s’adapte au transport : aucun départ sans capacité confirmée. Remplissage cible ${pct(REF.fill.cible)}, seuil d’alerte ${pct(REF.fill.alerte)}.`,`<label class="fl">Cycle<select id="pCy">${opt(REF.cycles.map(c=>[c.c,c.c+' – départ '+fr(c.dep)+(c.ok?'':' (indicatif)')]),planCy)}</select></label><label class="fl">Affichage<select id="pAll"><option value="0">Sous-parcours avec commandes</option><option value="1" ${planAll?'selected':''}>Les 44 sous-parcours</option></select></label>`)+
  `<div class="kpis">${J.map(([k,l,d])=>`<div class="kpi ${today()>d?'k-bad':'k-info'}"><b>${k}</b><span>${fr(d)} · ${esc(l)}</span></div>`).join('')}</div>
  ${cy.ok?'':'<div class="note w">Dates de C2 à C4 indicatives : à confirmer par la Direction. Seul le démarrage de C1 au 08/02/2027 est validé.</div>'}`+
  table([{t:'Sous-parcours',f:r=>`<b>${r.s.code}</b> ${esc(r.s.nom)}<br><span class="small muted">${r.s.seq.length} arrêt(s) · ${fmt(r.s.km)} km · ${fmt(r.s.j,1)} j</span>`},{t:'Cmd',r:1,f:r=>r.os.length},{t:'Colis',r:1,f:r=>fmt(r.colis)},{t:'kg',r:1,f:r=>fmt(r.kg)},{t:'m³',r:1,f:r=>fmt(r.m3,2)},{t:'Véhicule du plan V11',f:r=>`<span class="small">${esc(r.s.veh)}</span>`},{t:'Proposition WMS',f:r=>r.v?`${r.v.n} × ${esc(r.v.lib)}`:'—'},{t:'Remplissage',f:r=>r.v?`${bar(r.v.fill,r.v.fill>=.95?'var(--green)':r.v.fill>=.8?'var(--orange)':'var(--red)')}<span class="small">${pct(r.v.fill)} vol. · ${pct(r.v.fillKg)} poids</span>`:'—'},{t:'Statut',f:r=>r.v?pill(r.v.statut,{PLEIN:'ok','À COMPLÉTER':'warn',MUTUALISER:'bad','EN PASSAGE':'info'}[r.v.statut]):'—'},{t:'Mission',f:r=>r.ms?`<span class="mono small">${r.ms.id}</span><br>${pill(r.ms.statut,r.ms.stopgo==='GO'?'ok':r.ms.stopgo==='NO-GO'?'bad':'info')}`:'—'},{t:'',f:r=>!r.os.length?'':!r.ms?`<button class="btn s p" data-x="planRes" data-a="${r.s.code}">Réserver J-20</button>`:!r.ms.stopgo?`<button class="btn s n" data-x="stopGo" data-a="${r.ms.id}">Stop / go J-15</button>`:`<button class="btn s" data-x="misView" data-a="${r.ms.id}">Chargement</button>`}],rows,{empty:'Aucune commande validée sur ce cycle. Validez des commandes pour les voir regroupées par sous-parcours.'})+
  `<div class="card"><h2>Règles appliquées</h2><div class="grid g3 small">
  <div><b>Choix du véhicule</b><br>Minimise le nombre de véhicules × (volume + 15 m³), dans la limite de la classe d’accès de la route (4x4 de bout en bout, barge, piste). Les sous-parcours « en passage » sont livrés par le camion d’une autre route.</div>
  <div><b>Décision selon le remplissage</b><br>${pill('PLEIN','ok')} ≥ 95 % : expédier · ${pill('À COMPLÉTER','warn')} 80–95 % : ajouter des commandes du même sous-parcours ou avancer une commande du cycle suivant · ${pill('MUTUALISER','bad')} &lt; 80 % : regrouper avec le sous-parcours voisin ou choisir un véhicule plus petit.</div>
  <div><b>Chargement</b><br>Ordre inverse de livraison : le dernier arrêt est chargé en premier, contre la cabine ; le premier arrêt est chargé en dernier, près des portes. Transbordement interdit (accord-cadre 3PL).</div></div></div>`};
BIND.plan=()=>{$('#pCy').onchange=e=>{planCy=e.target.value;refresh()};$('#pAll').onchange=e=>{planAll=e.target.value==='1';refresh()}};
ACT.planRes=code=>{if(!need('plan'))return;const r=planRows(planCy).find(x=>x.s.code===code);const internal=/interne/.test(r.s.veh);
  const fleet=FLEET.filter(f=>internal?f.type==='Camion':f.type==='4x4');
  modal('Réservation J-20 – '+code,`<p>${esc(r.s.nom)} · ${r.os.length} commande(s) · ${fmt(r.m3,2)} m³ · ${fmt(r.kg)} kg · proposition : ${r.v.n} × ${esc(r.v.lib)} (${pct(r.v.fill)})</p>
  <div class="fx"><label>Source<select id="rSrc"><option ${internal?'selected':''}>Interne</option><option ${internal?'':'selected'}>3PL</option></select></label><label>Véhicule interne (flotte SALAMA)<select id="rVeh"><option value="">—</option>${fleet.map(f=>`<option value="${f.imm}">${esc(f.mod)} · ${f.imm} · ${f.t} t · ${f.m3} m³ · ${f.etat}</option>`).join('')}</select></label><label>Transporteur 3PL (liste de rang)<select id="rT">${S.transporteurs.map(t=>`<option value="${t.id}">${esc(t.nom)} – ${esc(t.lot)}</option>`).join('')}</select></label></div>
  ${r.v.statut==='MUTUALISER'?`<div class="note b">Remplissage sous 80 % : envisager la mutualisation avec un sous-parcours voisin de la route ${r.s.route} (${SP.filter(s=>s.route===r.s.route&&s.code!==code).map(s=>s.code).join(', ')}) ou un véhicule plus petit.</div>`:''}`,
  `<button class="btn p" data-x="planResOk" data-a="${code}">Réserver et émettre le bon d’appel</button>`)};
ACT.planResOk=code=>{const r=planRows(planCy).find(x=>x.s.code===code);const src=$('#rSrc').value;const imm=$('#rVeh').value;const f=FLEET.find(x=>x.imm===imm);
  const ms={id:nextNo('mis','MIS-'),cycle:planCy,sp:code,orders:r.os.filter(o=>o.statut==='Validée').map(o=>o.no),veh:r.v,vehId:imm,source:src,transp:src==='Interne'?'T3':$('#rT').value,chauffeur:'',telCh:'',plaque:src==='Interne'?imm:'',modele:f?f.mod:'',statut:'Réservée J-20',depart:jalonDep(planCy),stopgo:'',scelle:'',resBy:me().nom,resTs:Date.now()};
  if(!ms.orders.length)return toast('Aucune commande validée non planifiée sur ce sous-parcours.',true);
  S.missions.push(ms);ms.orders.forEach(no=>{const o=S.orders.find(x=>x.no===no);o.statut='Planifiée';o.mission=ms.id;o.hist.push({ts:Date.now(),by:me().nom,a:'Planifiée '+ms.id,c:''})});
  audit('Planification',ms.id,`${code} · ${src} · ${r.v.n} × ${r.v.lib}`);closeModal();toast('Mission '+ms.id+' réservée (J-20).');refresh()};
ACT.stopGo=id=>{if(!need('stopgo'))return;const m=S.missions.find(x=>x.id===id);const os=m.orders.map(n=>S.orders.find(o=>o.no===n));
  const checks=[['Commandes gelées (validées DVM / DAS)',os.every(o=>o.gel||o.validePar)],['Volume et poids calculés',os.every(o=>o.calc&&o.calc.m3>0)],['Véhicule affecté ou bon d’appel 3PL émis',!!(m.vehId||m.source==='3PL')],['Remplissage ≥ 80 %',m.veh.fill>=.8||m.veh.statut==='EN PASSAGE'],['Stock libéré suffisant',os.every(o=>o.lignes.every(l=>dispo(l.art,'S1')>=l.qty))]];
  modal('Stop / go J-15 – '+id,table([{t:'Contrôle',f:c=>c[0]},{t:'Résultat',f:c=>c[1]?pill('Conforme','ok'):pill('Non conforme','bad')}],checks)+`<label class="fl">Arbitrage / commentaire DVM<textarea id="sgC"></textarea></label>`,
  `<button class="btn d" data-x="sgDo" data-a="${id}" data-b="NO-GO">NO-GO (replanifier)</button><button class="btn p" data-x="sgDo" data-a="${id}" data-b="GO" ${checks.every(c=>c[1])?'':'data-arb="1"'}>GO${checks.every(c=>c[1])?'':' avec arbitrage'}</button>`)};
ACT.sgDo=(id,d,btn)=>{const m=S.missions.find(x=>x.id===id);const c=$('#sgC').value.trim();if(btn&&btn.dataset.arb&&d==='GO'&&!c)return toast('Un GO malgré un contrôle non conforme exige un arbitrage écrit.',true);
  m.stopgo=d;m.sgBy=me().nom;m.sgC=c;m.statut=d==='GO'?'GO – en préparation':'NO-GO – à replanifier';
  m.orders.forEach(n=>{const o=S.orders.find(x=>x.no===n);if(d==='GO')o.statut='En préparation';else{o.statut='Validée';o.mission=''}});if(d==='NO-GO')m.orders=[];
  audit('Stop / go J-15',id,d+(c?' – '+c:''));closeModal();toast(id+' : '+d);refresh()};

/* ---------------- Préparation FEFO ---------------- */
VIEWS.preparation=()=>{const ms=S.missions.filter(m=>m.stopgo==='GO'&&m.statut==='GO – en préparation');const wv=S.waves.filter(w=>w.statut!=='Contrôlée');
  return ph('Préparation des commandes (picking FEFO)','Une mission GO devient une vague de préparation. Le WMS alloue les lots par FEFO (statut libéré, durée résiduelle minimale) et guide le préparateur dans l’ordre des adresses. Chaque prélèvement est contrôlé par scan emplacement – lot – quantité (OUT-002 à OUT-004).')+
  `<div class="card"><h2>Missions GO à lancer</h2>${table([{t:'Mission',f:m=>`<span class="mono">${m.id}</span>`},{t:'Sous-parcours',k:'sp'},{t:'Commandes',f:m=>m.orders.join(', ')},{t:'',f:m=>S.waves.find(w=>w.mission===m.id)?pill('Vague créée','info'):`<button class="btn s p" data-x="waveGen" data-a="${m.id}">Générer la vague FEFO</button>`}],ms,{empty:'Aucune mission GO en attente de préparation.'})}</div>`+
  wv.map(w=>`<div class="card"><div class="row" style="justify-content:space-between"><h2>Vague ${w.id} · mission ${w.mission}</h2>${pill(w.statut,w.statut==='Préparée'?'ok':'warn')}</div>`+
   prepOrders(w)+table([{t:'#',r:1,f:l=>l.seq},{t:'Adresse',f:l=>locTag(l.loc)},{t:'Article',f:l=>artLabel(l.art)},{t:'Lot',f:l=>`<span class="mono">${esc(lotOf(l.lotId).lot)}</span><br>${expPill(lotOf(l.lotId).exp)}`},{t:'Commande',k:'order'},{t:'Mode',f:l=>l.mode==='Carton'?pill('Cartons d’origine','info'):pill('UD vrac','warn')},{t:'À prélever',r:1,f:l=>fmt(l.qty)},{t:'Scan',f:l=>l.annule?pill('Annulé – '+l.motifAnnul,'bad'):l.done?pill('Prélevé '+fmt(l.picked)+' par '+l.by,'ok')+(l.realloc?' '+pill('réalloué','info'):''):`<div class="row"><input class="mono" data-scan="click" id="pk_${w.id}_${l.seq}" placeholder="adresse ou GS1" style="width:170px"><input type="number" id="pq_${w.id}_${l.seq}" value="${l.qty}" style="width:80px"><button class="btn s p" data-x="pickDo" data-a="${w.id}" data-b="${l.seq}">OK</button></div>`}],w.lignes)+
   (w.ruptures.length?`<div class="note b" style="margin-top:8px">Ruptures : ${w.ruptures.map(r=>esc(ART[r.art].des)+' – '+fmt(r.qty)+' UD (reste à livrer créé)').join(' ; ')}</div>`:'')+`</div>`).join('')};
ACT.waveGen=id=>{if(!(can('pick')||can('put')))return deny('pick');const m=S.missions.find(x=>x.id===id);const lines=[],rupt=[];
  m.orders.forEach(n=>{const o=S.orders.find(x=>x.no===n);o.lignes.forEach(l=>{const a=ART[l.art];let full=Math.floor(l.qty/a.udc)*a.udc,rem=l.qty-full;
    const alloc=(qty,mode)=>{fefoLots(l.art,'S1').forEach(s=>{if(qty<=0)return;const reserved=sum(lines.filter(x=>x.sid===s.id),x=>x.qty);const av=s.qty-reserved-reservedQty(s.id);if(av<=0)return;
      if(mode==='Vrac'&&LOC[s.loc].zone!=='P'&&fefoLots(l.art,'S1').some(z=>LOC[z.loc].zone==='P'&&z.qty-sum(lines.filter(x=>x.sid===z.id),x=>x.qty)>0&&lotOf(z.lotId).exp<=lotOf(s.lotId).exp))return;
      const q=Math.min(qty,av);lines.push({sid:s.id,loc:s.loc,lotId:s.lotId,art:l.art,order:n,qty:q,mode});qty-=q});return qty};
    let left=alloc(full,'Carton')+0;left=alloc(rem+left,'Vrac');if(left>0){rupt.push({art:l.art,qty:left,order:n});S.ral.push({id:uid('RAL'),order:n,art:l.art,qty:left,motif:'Rupture à la préparation',statut:'Ouvert',ts:Date.now()})}})});
  lines.sort((a,b)=>a.loc.localeCompare(b.loc)).forEach((l,i)=>l.seq=i+1);
  S.waves.push({id:nextNo('wav','VAG-'),mission:id,lignes:lines,ruptures:rupt,statut:'En cours',ts:Date.now()});audit('Préparation',id,'Vague FEFO générée : '+lines.length+' prélèvements');refresh()};
function prepOrders(w){const ords=[...new Set(w.lignes.map(l=>l.order))];return `<h3>Prise en charge des commandes</h3>`+table([{t:'Commande',f:n=>`<span class="mono">${n}</span>`},{t:'Lignes',r:1,f:n=>`${w.lignes.filter(l=>l.order===n&&l.done).length} / ${w.lignes.filter(l=>l.order===n).length}`},{t:'Colis prévus',r:1,f:n=>fmt(S.orders.find(o=>o.no===n)?.calc.colis)},{t:'Préparateur',f:n=>{const t=prepTask(n);return t?esc(staffNom(t.staff)):'—'}},{t:'Prise',f:n=>hm(prepTask(n)?.start)},{t:'Fin',f:n=>hm(prepTask(n)?.end)},{t:'Durée',f:n=>{const t=prepTask(n);return t?pill(dur((t.end||Date.now())-t.start),t.end?'ok':'warn'):'—'}},{t:'',f:n=>prepTask(n)?'':`<button class="btn s p" data-x="ordTake" data-a="${w.id}" data-b="${n}">Prendre la commande</button>`}],ords)+'<h3 style="margin-top:8px">Prélèvements</h3>'}
function prepTask(no){ensureHR();return S.tasks.filter(t=>t.type==='Préparation'&&t.ref===no).sort((a,b)=>b.start-a.start)[0]}
ACT.ordTake=(wid,no)=>{if(!need('pick'))return;const st=staffOfUser(me().id);if(!st)return toast('Profil non rattaché à un agent de l’entrepôt (Ressources humaines).',true);
  const busy=S.tasks.find(t=>t.staff===st.id&&t.statut==='En cours');if(busy)return toast('Vous avez déjà une tâche en cours : '+busy.type+' '+busy.ref+'.',true);
  taskStart(st.id,'Préparation',no,{wave:wid});audit('Préparation',no,'Prise en charge par '+st.nom);toast('Commande '+no+' prise en charge à '+hm(Date.now())+'.');refresh()};
ACT.pickDo=(wid,seq)=>{if(!need('pick'))return;const w=S.waves.find(x=>x.id===wid);const l=w.lignes.find(x=>x.seq==seq);
  if(l.annule)return toast('Ligne annulée : '+l.motifAnnul,true);{const lt=lotOf(l.lotId);if(lt.statut!=='Libéré'||monthsLeft(lt.exp)<=0){lotUnavailable(l.lotId,lt.statut!=='Libéré'?lt.statut.toLowerCase():'lot périmé');refresh();return toast('Lot '+lt.lot+' non disponible ('+lt.statut+') : prélèvement bloqué, réallocation FEFO effectuée.',true)}}
  {const t0=prepTask(l.order);const st0=staffOfUser(me().id);if(t0&&t0.statut==='En cours'&&st0&&t0.staff!==st0.id)return toast('Commande '+l.order+' prise en charge par '+staffNom(t0.staff)+'.',true)}const v=($(`#pk_${wid}_${seq}`).value||'').trim();const q=+$(`#pq_${wid}_${seq}`).value;
  if(v){const r=parseGS1(v);if(r?.type==='loc'&&r.loc!==l.loc)return toast('Mauvais emplacement : attendu '+l.loc+' (OUT-004).',true);if(r?.type==='gs1'){if(r.gtin&&r.gtin!==ART[l.art].gtin)return toast('Mauvais article scanné : prélèvement bloqué.',true);if(r.lot&&r.lot!==lotOf(l.lotId).lot)return toast('Mauvais lot : le FEFO impose le lot '+lotOf(l.lotId).lot+'.',true)}}
  if(!(q>0)||q>l.qty)return toast('Quantité invalide.',true);
  const s=S.stock.find(x=>x.id===l.sid);if(!s||s.qty<q)return toast('Stock insuffisant à l’adresse.',true);s.qty-=q;
  const exp=`S1-EXP-${S.missions.find(m=>m.id===w.mission).sp.slice(0,3).replace('R','R')}`;const eloc=LOC[exp]?exp:'S1-EXP-R01';
  S.stock.push({id:uid('ST'),lotId:l.lotId,loc:eloc,qty:q,sscc:'',order:l.order});l.done=true;l.scan=!!v;l.picked=q;l.by=me().nom;l.byId=me().id;
  if(q<l.qty)S.ral.push({id:uid('RAL'),order:l.order,art:l.art,qty:l.qty-q,motif:'Écart au prélèvement',statut:'Ouvert',ts:Date.now()});
  {const st=staffOfUser(me().id);if(st){let t=prepTask(l.order);if(!t||t.statut!=='En cours')t=t&&t.statut==='Terminée'?null:taskStart(st.id,'Préparation',l.order,{wave:wid});const ol=w.lignes.filter(x=>x.order===l.order&&!x.annule);if(t&&ol.every(x=>x.done))taskEnd(t,{lignes:ol.length,colis:S.orders.find(o=>o.no===l.order)?.calc.colis||0})}}
  if(w.lignes.every(x=>x.done||x.annule)){w.statut='Préparée';w.prepTs=Date.now();audit('Préparation',w.id,'Vague préparée – en zone d’expédition '+eloc)}refresh()};

/* ---------------- Contrôle et emballage ---------------- */
VIEWS.emballage=()=>{const wv=S.waves.filter(w=>w.statut==='Préparée'||w.statut==='Contrôlée');
  return ph('Contrôle final et emballage','Le contrôleur (différent du préparateur) vérifie chaque ligne, puis le WMS constitue les colis : cartons d’origine, cartons de reconditionnement 001 / 003 / 007 pour le vrac, palette mixte. Chaque colis reçoit un SSCC et une étiquette logistique GS1-128 avec QR (OUT-006, OUT-007).')+
  (wv.length?wv.map(w=>{const m=S.missions.find(x=>x.id===w.mission);const cs=S.colis.filter(c=>c.mission===w.mission);return `<div class="card"><div class="row" style="justify-content:space-between"><h2>Vague ${w.id} · ${m.sp} · ${m.orders.join(', ')}</h2><div class="row">${w.statut==='Préparée'?`<label class="fl" style="flex-direction:row;align-items:center;gap:6px">Erreurs constatées<input type="number" id="err_${w.id}" value="0" min="0" style="width:70px"></label><button class="btn n s" data-x="ctrlDo" data-a="${w.id}">Contrôler la vague</button>`:''}${w.statut==='Contrôlée'&&!cs.length?`<button class="btn p s" data-x="packDo" data-a="${w.id}">Constituer les colis (SSCC)</button>`:''}${cs.length?`<button class="btn s" data-x="labSSCC" data-a="${w.mission}">Étiquettes SSCC (PDF)</button>`:''}</div></div>`+
   table([{t:'Commande',k:'order'},{t:'Article',f:l=>esc(ART[l.art].des)},{t:'Lot',f:l=>esc(lotOf(l.lotId).lot)},{t:'Prélevé',r:1,f:l=>fmt(l.picked)},{t:'Préparateur',k:'by'}],w.lignes)+
   (cs.length?`<h3 style="margin-top:10px">Colis</h3>`+table([{t:'SSCC',f:c=>`<span class="mono">${c.sscc}</span>`},{t:'Commande',k:'order'},{t:'Type',k:'type'},{t:'Contenu',f:c=>c.contenu.map(x=>esc(ART[x.art].des)+' × '+fmt(x.qty)).join('<br>')},{t:'kg',r:1,f:c=>fmt(c.kg,1)},{t:'m³',r:1,f:c=>fmt(c.m3,3)},{t:'Statut',f:c=>pill(c.statut,'info')}],cs):'')+`</div>`}).join(''):'<div class="card muted">Aucune vague préparée à contrôler.</div>')};
ACT.ctrlDo=wid=>{if(!need('ctrl'))return;const w=S.waves.find(x=>x.id===wid);if(w.lignes.some(l=>l.byId===me().id))return toast('Séparation des tâches : le contrôleur doit être différent du préparateur.',true);
  const nerr=+($('#err_'+wid)?.value||0);if(nerr>0){const pt=S.tasks.filter(t=>t.type==='Préparation'&&t.wave===wid);if(pt[0])pt[0].err=(pt[0].err||0)+nerr}
  {const st=staffOfUser(me().id);if(st){const t=taskStart(st.id,'Contrôle',w.mission,{wave:wid});t.start=w.prepTs&&w.prepTs<Date.now()?Math.max(w.prepTs,Date.now()-36e5):Date.now()-15*6e4;taskEnd(t,{lignes:w.lignes.length,colis:sum(S.missions.find(m=>m.id===w.mission).orders,n=>S.orders.find(o=>o.no===n)?.calc.colis||0),err:0})}}
  w.statut='Contrôlée';w.ctrlBy=me().nom;w.errCtrl=nerr;S.missions.find(m=>m.id===w.mission).orders.forEach(n=>{const o=S.orders.find(x=>x.no===n);o.statut='Contrôlée'});audit('Contrôle',wid,'Contrôle final conforme');refresh()};
ACT.packDo=wid=>{if(!need('pack'))return;const w=S.waves.find(x=>x.id===wid);const m=S.missions.find(x=>x.id===w.mission);
  m.orders.forEach(n=>{const o=S.orders.find(x=>x.no===n);const ls=w.lignes.filter(l=>l.order===n);
    ls.filter(l=>l.mode==='Carton').forEach(l=>{const a=ART[l.art];const nc=Math.floor(l.picked/a.udc);for(let i=0;i<nc;i++)S.colis.push({sscc:mkSSCC(S.seq.sscc++),order:n,mission:m.id,type:'Carton d’origine',kg:a.ckg,m3:cm3(a.cl,a.cw,a.ch),contenu:[{art:l.art,lotId:l.lotId,qty:a.udc}],statut:'Emballé'})});
    const vr=ls.filter(l=>l.mode==='Vrac');if(vr.length){const c=colisage(vr.map(l=>({art:l.art,qty:Math.min(l.picked,ART[l.art].udc-1)})));
      c.recon.forEach(r=>{for(let i=0;i<r.n;i++)S.colis.push({sscc:mkSSCC(S.seq.sscc++),order:n,mission:m.id,type:'Carton '+r.carton+' – '+r.tr,kg:r.kg/r.n,m3:r.m3/r.n,contenu:i===0?vr.filter(l=>ART[l.art].tr===r.tr).map(l=>({art:l.art,lotId:l.lotId,qty:l.picked})):[],statut:'Emballé'})})}
    o.statut='Emballée'});
  S.stock.filter(s=>m.orders.includes(s.order)&&LOC[s.loc]?.zone==='EXP').forEach(s=>s.packed=true);
  audit('Emballage',m.id,'Colis constitués et étiquetés SSCC');toast('Colis constitués : imprimez les étiquettes SSCC.');refresh()};
ACT.labSSCC=mid=>{const m=S.missions.find(x=>x.id===mid);const cs=S.colis.filter(c=>c.mission===mid);const d=pdfDoc('Étiquettes logistiques GS1 – '+mid,m.sp+' · '+cs.length+' colis');let y=36;
  cs.forEach((c,i)=>{if(y>230){d.addPage();y=20}const o=S.orders.find(x=>x.no===c.order);const dest=DEST.find(x=>x.code===o.dest);d.setDrawColor(19,48,74);d.rect(12,y,186,56);
    d.setFont('helvetica','bold');d.setFontSize(11);d.setTextColor(19,48,74);d.text('À : '+o.destNom+'  ·  '+o.sp+' arrêt '+(dest?.ordre||'')+'  ·  '+o.no,16,y+7);
    d.setFont('helvetica','normal');d.setFontSize(8.5);d.setTextColor(40);d.text('De : SALAMA 1 – Anosiala  ·  '+c.type+'  ·  '+fmt(c.kg,1)+' kg  ·  colis '+(i+1)+'/'+cs.length,16,y+13);
    d.text(c.contenu.slice(0,3).map(x=>ART[x.art].des+' × '+x.qty+' (lot '+lotOf(x.lotId).lot+')').join(' ; ').slice(0,150),16,y+18);
    const b=barcodeDataURL(c.sscc);if(b)d.addImage(b,'PNG',16,y+21,120,32);const q=qrDataURL(dlSSCC(c.sscc),3);if(q)d.addImage(q,'PNG',160,y+20,32,32);y+=62});
  d.__foot();saveFile('Etiquettes_SSCC_'+mid+'.pdf',d.output('arraybuffer'),'application/pdf')};

/* ---------------- Chargement et expédition ---------------- */
VIEWS.expedition=()=>{const ms=S.missions.filter(m=>m.orders.length&&m.orders.every(n=>['Emballée'].includes(S.orders.find(o=>o.no===n)?.statut)));
  return ph('Chargement et expédition','Chargement en ordre inverse des arrêts, scan de chaque SSCC, scellé, ordre de mission. Le départ confirme l’expédition à X3 avec lots, quantités, SSCC, véhicule et date (OUT-008, TMS-004).')+
  (ms.length?ms.map(m=>{const cs=S.colis.filter(c=>c.mission===m.id&&c.statut!=='Retiré');const sp=SP.find(s=>s.code===m.sp);const ordStop=no=>{const o=S.orders.find(x=>x.no===no);return sp.seq.indexOf(o.destNom)+1};const sorted=cs.slice().sort((a,b)=>ordStop(b.order)-ordStop(a.order));
   return `<div class="card"><div class="row" style="justify-content:space-between"><h2>${m.id} · ${m.sp} · ${esc(sp.nom)}</h2><div class="row"><button class="btn s" data-x="misPDF" data-a="${m.id}">Ordre de mission (PDF)</button><button class="btn s o" data-x="misDepart" data-a="${m.id}">Confirmer le départ</button></div></div>
   <div class="fx"><label>Transporteur<select id="mt_${m.id}">${S.transporteurs.map(t=>`<option value="${t.id}" ${t.id===m.transp?'selected':''}>${esc(t.nom)}</option>`).join('')}</select></label><label>Chauffeur<input id="mc_${m.id}" value="${esc(m.chauffeur)}"></label><label>Téléphone<input id="mp_${m.id}" value="${esc(m.telCh)}"></label><label>Immatriculation<input id="mi_${m.id}" value="${esc(m.plaque)}"></label><label>Modèle<input id="mm_${m.id}" value="${esc(m.modele)}"></label><label>N° de scellé<input id="ms_${m.id}" value="${esc(m.scelle)}"></label></div>
   <h3 style="margin-top:10px">Plan de chargement (du fond du camion vers les portes)</h3>`+table([{t:'Ordre',r:1,f:(c)=>sorted.indexOf(c)+1},{t:'Arrêt',f:c=>{const o=S.orders.find(x=>x.no===c.order);return 'n° '+ordStop(c.order)+' – '+esc(o.destNom)}},{t:'SSCC',f:c=>`<span class="mono">${c.sscc}</span>`},{t:'Type',k:'type'},{t:'kg',r:1,f:c=>fmt(c.kg,1)},{t:'Scan chargement',f:c=>c.statut==='Bloqué'?pill('Bloqué – '+c.motifBlocage,'bad')+` <button class="btn s d" data-x="colisRetirer" data-a="${c.sscc}">Retirer</button>`:c.statut==='Chargé'?pill('Chargé','ok'):`<div class="row"><input class="mono" data-scan="click" id="ld_${c.sscc}" placeholder="(00)${c.sscc}" style="width:200px"><button class="btn s p" data-x="loadDo" data-a="${c.sscc}">OK</button></div>`}],sorted)+`</div>`}).join(''):'<div class="card muted">Aucune mission entièrement emballée.</div>')+
  `<div class="card"><h2>Missions en transit</h2>${table([{t:'Mission',k:'id'},{t:'Sous-parcours',k:'sp'},{t:'Véhicule',f:m=>esc((m.modele||'')+' '+(m.plaque||''))},{t:'Chauffeur',k:'chauffeur'},{t:'Départ',f:m=>fr(m.depart)},{t:'POD au plus tard',f:m=>fr(addD(m.depart,7))}],S.missions.filter(m=>m.statut==='En transit'),{empty:'Aucune mission en transit.'})}</div>`};
ACT.loadDo=sscc=>{if(!need('load'))return;{const c0=S.colis.find(x=>x.sscc===sscc);if(c0&&c0.statut==='Bloqué')return toast('Colis bloqué : '+c0.motifBlocage+'. Retirez-le avant le départ.',true)}const v=($('#ld_'+sscc).value||'').trim();if(v){const r=parseGS1(v);const got=r?.sscc||v.replace(/\D/g,'');if(got!==sscc)return toast('SSCC scanné différent du colis attendu : chargement refusé.',true)}
  const c=S.colis.find(x=>x.sscc===sscc);c.scanLoad=!!v;c.statut='Chargé';c.loadBy=me().nom;c.loadTs=Date.now();refresh()};
function misSave(m){m.transp=$('#mt_'+m.id)?.value||m.transp;m.chauffeur=$('#mc_'+m.id)?.value||m.chauffeur;m.telCh=$('#mp_'+m.id)?.value||m.telCh;m.plaque=$('#mi_'+m.id)?.value||m.plaque;m.modele=$('#mm_'+m.id)?.value||m.modele;m.scelle=$('#ms_'+m.id)?.value||m.scelle}
ACT.misDepart=id=>{if(!need('load'))return;const m=S.missions.find(x=>x.id===id);misSave(m);const cs=S.colis.filter(c=>c.mission===id&&c.statut!=='Retiré');
  if(cs.some(c=>c.statut==='Bloqué'))return toast('Départ refusé : un colis contient un lot bloqué, rappelé ou en quarantaine. Retirez-le d’abord.',true);
  if(cs.some(c=>c.statut!=='Chargé'))return toast('Tous les colis doivent être scannés au chargement (TMS-004).',true);if(!m.plaque||!m.chauffeur||!m.scelle)return toast('Chauffeur, immatriculation et scellé obligatoires.',true);
  m.statut='En transit';m.depart=iso(today());m.departTs=Date.now();S.stock.filter(s=>m.orders.includes(s.order)&&LOC[s.loc]?.zone==='EXP').forEach(s=>s.qty=0);
  m.orders.forEach(n=>{const o=S.orders.find(x=>x.no===n);o.statut='En transit';x3('Livraison expédiée (SDH)','Bon de livraison',n,{mission:id,sscc:cs.filter(c=>c.order===n).map(c=>c.sscc),vehicule:m.plaque})});
  audit('Expédition',id,'Départ – '+m.plaque+' – scellé '+m.scelle);toast('Départ confirmé : POD attendue au plus tard le '+fr(addD(today(),7))+'.');refresh()};
ACT.misView=id=>{location.hash='#expedition'};
ACT.misPDF=id=>{const m=S.missions.find(x=>x.id===id);misSave(m);const t=S.transporteurs.find(x=>x.id===m.transp);const sp=SP.find(s=>s.code===m.sp);const d=pdfDoc('Ordre de mission – '+id,m.sp+' · '+sp.nom+' · cycle '+m.cycle);
  d.setFontSize(9);d.setTextColor(30);[['Transporteur',t?.nom||''],['Chauffeur',m.chauffeur+' · '+m.telCh],['Véhicule',m.modele+' · '+m.plaque],['Scellé',m.scelle],['Trajet',sp.seq.join(' → ')],['Délai POD','au plus tard 7 jours après livraison ; aucun frais supplémentaire, transbordement interdit']].forEach(([k,v],i)=>{d.setFont('helvetica','bold');d.text(k,14,40+i*6);d.setFont('helvetica','normal');d.text(d.splitTextToSize(String(v),150),50,40+i*6)});
  const cs=S.colis.filter(c=>c.mission===id);pdfTable(d,82,['Arrêt','Commande','SSCC','Type','kg'],cs.map(c=>{const o=S.orders.find(x=>x.no===c.order);return [o.destNom,o.no,c.sscc,c.type,fmt(c.kg,1)]}),[40,30,45,50,20]);d.__foot();saveFile('Ordre_mission_'+id+'.pdf',d.output('arraybuffer'),'application/pdf')};

/* ---------------- Livraison et POD ---------------- */
VIEWS.pod=()=>{const tr=S.missions.filter(m=>m.statut==='En transit');
  return ph('Livraison et preuve de livraison (POD)','Le réceptionnaire contrôle produits, lots, SSCC et quantités ; la POD électronique porte les identités du livreur et du réceptionnaire, les deux signatures, la date et l’heure, et un code QR avec empreinte qui rend toute modification détectable. Les écarts créent un reste à livrer ou un litige (DLV-001 à DLV-006).')+
  `<div class="note w">Délai contractuel 2027 : POD transmise sous 7 jours (J+7), le processus papier restant possible au démarrage. La POD électronique de ce module rend la remontée immédiate dès que le réseau revient.</div>`+
  `<div class="card"><h2>Livraisons en transit</h2>${table([{t:'Mission',f:m=>`<span class="mono">${m.id}</span>`},{t:'Arrêt / commande',f:m=>m.orders.map(n=>{const o=S.orders.find(x=>x.no===n);return `${esc(o.destNom)} · ${n} ${o.pod?pill('POD ✓','ok'):`<button class="btn s p" data-x="podNew" data-a="${n}">Enregistrer la réception</button>`}`}).join('<br>')},{t:'Départ',f:m=>fr(m.depart)},{t:'Échéance POD',f:m=>{const l=addD(m.depart,7);return pill(fr(l),today()>l?'bad':'info')}}],tr,{empty:'Aucune livraison en transit.'})}</div>`+
  `<div class="card"><h2>POD enregistrées</h2>${table([{t:'POD',f:p=>`<button class="btn s p" data-x="podShow" data-a="${p.no}">POD ✓ ${p.no}</button>`},{t:'Commande',k:'order'},{t:'Destination',f:p=>esc(S.orders.find(o=>o.no===p.order)?.destNom)},{t:'Reçu par',f:p=>esc(p.recNom+' – '+p.fonction)},{t:'Le',f:p=>frt(p.date)},{t:'Écarts',f:p=>{const e=p.lignes.filter(l=>l.recu!==l.qty);return (e.length?pill(e.length+' ligne(s)','warn'):pill('Aucun','ok'))+(p.excursion?' '+pill('Excursion '+p.excursion,'bad'):'')+(p.horsLigne?' '+pill(p.syncTs?'Hors ligne – synchronisée '+hm(p.syncTs):'Hors ligne – en attente','warn'):'')}}],S.pods,{empty:'Aucune POD.'})}</div>`+
  `<div class="card"><h2>Restes à livrer et litiges</h2>${table([{t:'Commande',k:'order'},{t:'Article',f:r=>esc(ART[r.art]?.des)},{t:'Qté',r:1,f:r=>fmt(r.qty)},{t:'Motif',k:'motif'},{t:'Statut',f:r=>pill(r.statut,r.statut==='Ouvert'?'warn':'ok')},{t:'',f:r=>r.statut==='Ouvert'?`<button class="btn s" data-x="ralClose" data-a="${r.id}">Solder (avoir / remplacement)</button>`:''}],S.ral,{empty:'Aucun reste à livrer.'})}</div>`};
ACT.ralClose=id=>{if(!(can('ord_ok')||can('plan')))return deny('ord_ok');const r=S.ral.find(x=>x.id===id);r.statut='Soldé';x3('Avoir / remplacement','Régularisation commande',r.order,{art:r.art,qte:r.qty});audit('Reste à livrer',r.order,'Soldé');refresh()};
function sigPad(id){const c=$('#'+id);const ctx=c.getContext('2d');const r=()=>{const b=c.getBoundingClientRect();c.width=b.width;c.height=b.height;ctx.lineWidth=2.2;ctx.lineCap='round';ctx.strokeStyle='#13304A'};r();let dr=false;
  const pos=e=>{const b=c.getBoundingClientRect();const t=e.touches?e.touches[0]:e;return [t.clientX-b.left,t.clientY-b.top]};
  c.onpointerdown=e=>{dr=true;c.dataset.signed='1';const [x,y]=pos(e);ctx.beginPath();ctx.moveTo(x,y);c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!dr)return;const [x,y]=pos(e);ctx.lineTo(x,y);ctx.stroke()};c.onpointerup=()=>dr=false}
ACT.podNew=(no,src)=>{if(!need('pod'))return;const o=S.orders.find(x=>x.no===no);const m=S.missions.find(x=>x.id===o.mission)||{};const t=S.transporteurs.find(x=>x.id===m.transp)||{};
  const cont=S.colis.filter(c=>c.order===no).flatMap(c=>c.contenu.map(x=>({...x,sscc:c.sscc})));const agg={};cont.forEach(x=>{const k=x.art+'|'+x.lotId;(agg[k]=agg[k]||{art:x.art,lotId:x.lotId,qty:0,colis:0});agg[k].qty+=x.qty;agg[k].colis++});const lines=cont.length?Object.values(agg):o.lignes.map(l=>({art:l.art,lotId:(fefoLots(l.art,'')[0]||{}).lotId,qty:l.qty,sscc:''}));ACT._podLines=lines;
  modal('Réception et POD – '+no,`<h3>Expédition</h3><div class="fx"><div class="fl">Commande<b>${no} (${o.x3})</b></div><div class="fl">Destinataire<b>${esc(o.destNom)}</b></div><div class="fl">Mission<b>${esc(m.id||'Livraison agence')}</b></div><div class="fl">Expéditeur<b>${esc(src||'SALAMA 1 – Anosiala')}</b></div></div>
  <h3>Transporteur ou 3PL</h3><div class="fx"><label>Société<input id="pT" value="${esc(t.nom||'')}"></label><label>Adresse<input id="pA" value="${esc(t.adr||'')}"></label><label>Livreur<input id="pL" value="${esc(m.chauffeur||'')}"></label><label>Téléphone<input id="pTel" value="${esc(m.telCh||'')}"></label><label>Immatriculation<input id="pPl" value="${esc(m.plaque||'')}"></label><label>Modèle du camion<input id="pMo" value="${esc(m.modele||'')}"></label></div>
  <h3>Réceptionnaire</h3><div class="fx"><label>Nom<input id="rN"></label><label>Téléphone<input id="rT"></label><label>Grade<input id="rG"></label><label>Fonction<input id="rF"></label><label>Qualité<select id="rQ"><option>Responsable de la réception</option><option>Pharmacien / dépositaire</option><option>Mandataire désigné</option></select></label><label>Date et heure de réception<input id="rD" type="datetime-local" value="${new Date(Date.now()-new Date().getTimezoneOffset()*6e4).toISOString().slice(0,16)}"></label><label>Coordonnées GPS (facultatif)<input id="rGps" placeholder="-18.8792, 47.5079"></label>${lines.some(l=>ART[l.art]?.temp.startsWith('Froid'))?'<label>Température à réception, produits 2–8 °C (°C)<input id="rTmp" type="number" step=".1"></label><label>Enregistreur / indicateur de température<select id="rInd"><option>Conforme</option><option>Alarme déclenchée</option><option>Absent ou illisible</option></select></label>':''}</div>${S.offline?'<div class="note w">Mode dégradé : la POD sera conservée sur l’appareil et synchronisée une seule fois au retour du réseau.</div>':''}
  <h3>Produits</h3>`+table([{t:'Article',f:l=>esc(ART[l.art]?.des)},{t:'GTIN',f:l=>`<span class="mono small">${ART[l.art]?.gtin}</span>`},{t:'Lot',f:l=>esc(lotOf(l.lotId)?.lot||'')},{t:'Péremption',f:l=>fr(lotOf(l.lotId)?.exp)},{t:'Expédié',r:1,f:l=>fmt(l.qty)},{t:'Reçu',f:(l)=>`<input type="number" class="pR" data-i="${lines.indexOf(l)}" value="${l.qty}" style="width:90px">`},{t:'Motif d’écart',f:l=>`<select class="pM" data-i="${lines.indexOf(l)}"><option value="">—</option><option>Manquant</option><option>Endommagé</option><option>Refusé – péremption</option><option>Excédent</option></select>`}],lines)+
  `<h3>Signatures manuscrites numériques</h3><div class="grid g2">${sigBlock('sigR','Signature du réceptionnaire','rN')}${sigBlock('sigL','Signature du livreur','pL')}</div>`,
  `<button class="btn p" data-x="podSave" data-a="${no}">Valider la POD</button>`,{w:'1150px'});sigPad('sigR');sigPad('sigL')};
ACT.podSave=async no=>{const o=S.orders.find(x=>x.no===no);const lines=ACT._podLines.map((l,i)=>({...l,recu:+$$('.pR')[i].value,motif:$$('.pM')[i].value}));
  if(!$('#rN').value.trim()||!$('#rF').value.trim()||!$('#rT').value.trim())return toast('Nom, téléphone et fonction du réceptionnaire obligatoires.',true);
  if(!$('#sigR').dataset.signed||!$('#sigL').dataset.signed)return toast('Les deux signatures sont obligatoires : tracez une signature complète dans chaque cadre.',true);
  if(lines.some(l=>l.recu!==l.qty&&!l.motif))return toast('Chaque écart doit être motivé.',true);
  const thermo=!!$('#rTmp');const tmp=thermo?$('#rTmp').value:'';if(thermo&&tmp==='')return toast('Température à réception obligatoire pour les produits 2–8 °C.',true);
  const excur=thermo&&(+tmp<2||+tmp>8||$('#rInd').value!=='Conforme');
  const p={no:'POD-'+no.slice(4)+'-'+String(S.pods.length+1).padStart(2,'0'),mission:o.mission,order:no,date:new Date($('#rD').value).getTime()||Date.now(),transp:$('#pT').value,adrT:$('#pA').value,chauffeur:$('#pL').value,tel:$('#pTel').value,plaque:$('#pPl').value,modele:$('#pMo').value,
    recNom:$('#rN').value,recTel:$('#rT').value,grade:$('#rG').value,fonction:$('#rF').value,qualite:$('#rQ').value,gps:$('#rGps').value,lignes:lines,sigR:$('#sigR').toDataURL('image/png'),sigL:$('#sigL').toDataURL('image/png'),sigRMeta:sigMeta('sigR',$('#rN').value),sigLMeta:sigMeta('sigL',$('#pL').value),saisiPar:me().nom,ts:Date.now(),temp:tmp,indic:thermo?$('#rInd').value:'',horsLigne:!!S.offline};
  p.sigRHash=await sha256(p.sigR);p.sigLHash=await sha256(p.sigL);p.hash=await sha256(JSON.stringify({n:p.no,o:no,d:p.date,r:p.recNom,l:lines.map(l=>[ART[l.art]?.gtin,lotOf(l.lotId)?.lot,l.qty,l.recu]),sr:p.sigRHash,sl:p.sigLHash,mr:p.sigRMeta,ml:p.sigLMeta}));
  S.pods.unshift(p);o.pod=p.no;o.statut='Livrée';lines.filter(l=>l.recu<l.qty).forEach(l=>S.ral.push({id:uid('RAL'),order:no,art:l.art,qty:l.qty-l.recu,motif:l.motif,statut:'Ouvert',ts:Date.now()}));
  if(excur){const fl=[...new Set(lines.filter(l=>ART[l.art]?.temp.startsWith('Froid')).map(l=>l.lotId))];const e={id:nextNo('exc','EXC-'),type:'Transport',lieu:o.destNom+' (POD '+p.no+')',lots:fl,max:+tmp||0,start:Date.now()-36e5,end:Date.now(),duree:36e5,statut:'Ouverte',dest:true};S.excursions.unshift(e);p.excursion=e.id;audit('Chaîne du froid',e.id,'Excursion constatée à la livraison : '+tmp+' °C, indicateur '+$('#rInd').value+' – produits à isoler chez le destinataire en attente de décision AQ')}
  S.colis.filter(c=>c.order===no).forEach(c=>c.statut='Livré');const m=S.missions.find(x=>x.id===o.mission);if(m&&m.orders.every(n=>S.orders.find(x=>x.no===n).pod))m.statut='Livrée';
  x3('POD certifiée → facturation (SIH)','Facture sur quantités acceptées',p.no,{commande:o.x3,acceptees:lines.map(l=>[ART[l.art]?.x3,l.recu])});audit('POD',p.no,'Réception signée par '+p.recNom+' ('+p.fonction+')');closeModal();toast('POD '+p.no+' validée.');refresh();ACT.podShow(p.no)};
ACT.podShow=no=>{const p=S.pods.find(x=>x.no===no);const o=S.orders.find(x=>x.no===p.order);const qr=`POD|${p.no}|${p.order}|${frt(p.date)}|${p.recNom}|${(p.hash||'').slice(0,16)}`;
  modal('POD '+no,`<div class="row" style="justify-content:space-between"><img src="${LOGO_S}" alt="SALAMA" style="height:54px"><div style="text-align:right"><b>PREUVE DE LIVRAISON</b><br><span class="mono">${no}</span></div></div><div style="height:4px;background:var(--green);border-bottom:2px solid var(--orange)"></div>
  <div class="fx"><div class="fl">Commande<b>${p.order} · ${esc(o?.x3)}</b></div><div class="fl">Destinataire<b>${esc(o?.destNom)}</b></div><div class="fl">Transporteur<b>${esc(p.transp)} · ${esc(p.adrT||'')}</b></div><div class="fl">Livreur<b>${esc(p.chauffeur)} · ${esc(p.tel)}</b></div><div class="fl">Véhicule<b>${esc(p.modele)} · ${esc(p.plaque)}</b></div><div class="fl">Réceptionnaire<b>${esc(p.recNom)} · ${esc(p.recTel)}</b></div><div class="fl">Grade, fonction, qualité<b>${esc([p.grade,p.fonction,p.qualite].filter(Boolean).join(' · '))}</b></div><div class="fl">Reçu le<b>${frt(p.date)}</b></div></div>`+
  table([{t:'Article',f:l=>esc(ART[l.art]?.des)},{t:'GTIN',f:l=>`<span class="mono small">${ART[l.art]?.gtin}</span>`},{t:'Lot',f:l=>esc(lotOf(l.lotId)?.lot)},{t:'Péremption',f:l=>fr(lotOf(l.lotId)?.exp)},{t:'Expédié',r:1,f:l=>fmt(l.qty)},{t:'Reçu',r:1,f:l=>fmt(l.recu)},{t:'Écart',r:1,f:l=>l.recu-l.qty?pill(fmt(l.recu-l.qty),'bad'):'0'},{t:'Motif',k:'motif'}],p.lignes)+
  `<div class="row" style="justify-content:space-between;align-items:flex-end"><div class="row">${p.sigR?`<div><div class="small muted">Signature du réceptionnaire</div><img src="${p.sigR}" alt="Signature du réceptionnaire" style="height:90px;max-width:260px;border:1px solid var(--line);background:#fff"><div class="small">${esc(p.sigRMeta?.nom||p.recNom)}${p.sigRMeta?` · ${frt(p.sigRMeta.ts)} · ${esc(p.sigRMeta.appareil)}`:''}</div></div>`:''}${p.sigL?`<div><div class="small muted">Signature du livreur</div><img src="${p.sigL}" alt="Signature du livreur" style="height:90px;max-width:260px;border:1px solid var(--line);background:#fff"><div class="small">${esc(p.sigLMeta?.nom||p.chauffeur)}${p.sigLMeta?` · ${frt(p.sigLMeta.ts)} · ${esc(p.sigLMeta.appareil)}`:''}</div></div>`:''}</div><div style="text-align:center">${qrSVG(qr,104)}<div class="small mono">empreinte ${(p.hash||'démonstration').slice(0,16)}…</div></div></div>`,
  `<button class="btn p" data-x="podPDF" data-a="${no}">Télécharger en PDF</button>`,{w:'1000px'})};
ACT.podPDF=no=>{const p=S.pods.find(x=>x.no===no);const o=S.orders.find(x=>x.no===p.order);const d=pdfDoc('PREUVE DE LIVRAISON – '+no,'Commande '+p.order+' · '+(o?.x3||'')+' · '+(o?.destNom||''));
  const kv=[['Expédition',(p.mission||'')+' · SALAMA → '+(o?.destNom||'')],['Transporteur / 3PL',p.transp+' · '+(p.adrT||'')],['Livreur',p.chauffeur+' · '+p.tel],['Camion',p.modele+' · immatriculation '+p.plaque],['Réceptionnaire',p.recNom+' · '+p.recTel],['Grade / fonction / qualité',[p.grade,p.fonction,p.qualite].filter(Boolean).join(' · ')],['Date et heure de réception',frt(p.date)+(p.gps?' · GPS '+p.gps:'')]];
  d.setFontSize(9);kv.forEach(([k,v],i)=>{d.setFont('helvetica','bold');d.setTextColor(19,48,74);d.text(k,14,38+i*5.5);d.setFont('helvetica','normal');d.setTextColor(30);d.text(String(v),62,38+i*5.5)});
  let y=pdfTable(d,82,['Article','GTIN','Lot','Péremption','Expédié','Reçu','Écart','Motif'],p.lignes.map(l=>[ART[l.art]?.des,ART[l.art]?.gtin,lotOf(l.lotId)?.lot,fr(lotOf(l.lotId)?.exp),l.qty,l.recu,l.recu-l.qty,l.motif]),[46,28,22,20,15,14,12,29]);
  if(y>225){d.addPage();y=20}d.setFontSize(8);d.setTextColor(80);d.text('Signature du réceptionnaire',14,y+4);d.text('Signature du livreur',84,y+4);
  try{if(p.sigR)d.addImage(p.sigR,'PNG',14,y+6,62,26)}catch(e){}try{if(p.sigL)d.addImage(p.sigL,'PNG',84,y+6,62,26)}catch(e){}d.setDrawColor(200);d.rect(14,y+6,62,26);d.rect(84,y+6,62,26);
  d.setFontSize(7);d.setTextColor(40);const mr=p.sigRMeta,ml=p.sigLMeta;d.text(d.splitTextToSize((mr?.nom||p.recNom||'')+(mr?' · '+frt(mr.ts)+' · '+mr.appareil:''),62),14,y+36);d.text(d.splitTextToSize((ml?.nom||p.chauffeur||'')+(ml?' · '+frt(ml.ts)+' · '+ml.appareil:''),62),84,y+36);
  const q=qrDataURL(`POD|${p.no}|${p.order}|${frt(p.date)}|${p.recNom}|${(p.hash||'').slice(0,16)}`,3);if(q)d.addImage(q,'PNG',160,y+2,34,34);d.setTextColor(90);d.setFontSize(6.5);d.text('Empreinte SHA-256 de la POD (contenu + signatures) : '+(p.hash||'démonstration'),14,y+46);
  d.text('Signatures manuscrites numériques captées sur écran ; valeur juridique à confirmer selon le cadre malgache applicable.',14,y+50);d.__foot();saveFile(no+'.pdf',d.output('arraybuffer'),'application/pdf')};

/* ---------------- Agences régionales ---------------- */
VIEWS.agences=()=>{const ag=REF.agences.find(a=>a.code===S.site)||REF.agences[3];const st=S.stock.filter(s=>s.qty>0&&LOC[s.loc]?.site===ag.code);const inc=S.transfers.filter(t=>t.to===ag.code&&t.statut==='En transit');
  return ph('Agences régionales – '+ag.nom,'Réception par scan des transferts venant des entrepôts centraux, stock d’agence par emplacement, livraison à la plus petite unité de distribution (carton d’origine ou vrac) avec POD.',`<button class="btn p" data-x="agDel" data-a="${ag.code}">Livrer un client (POD)</button>`)+
  `${REF.agences.find(a=>a.code===S.site)?'':'<div class="note w">Sélectionnez une agence dans le sélecteur de site en haut de page. Affichage par défaut : Agence Toamasina.</div>'}
  <div class="card"><h2>Transferts entrants</h2>${table([{t:'N°',k:'no'},{t:'Article',f:t=>esc(ART[lotOf(t.lotId).art].des)},{t:'Lot',f:t=>esc(lotOf(t.lotId).lot)},{t:'Qté',r:1,f:t=>fmt(t.qty)},{t:'SSCC',f:t=>`<span class="mono small">${t.sscc||''}</span>`},{t:'',f:t=>`<button class="btn s p" data-x="trfRec" data-a="${t.no}">Réceptionner</button>`}],inc,{empty:'Aucun transfert en transit vers cette agence. Créez-en un depuis Stock › Transferts (type « Vers agence »).'})}</div>
  <div class="card"><h2>Stock de l’agence</h2>${table([{t:'Emplacement',f:s=>locTag(s.loc)},{t:'Article',f:s=>artLabel(lotOf(s.lotId).art)},{t:'Lot',f:s=>esc(lotOf(s.lotId).lot)},{t:'Péremption',f:s=>expPill(lotOf(s.lotId).exp)},{t:'Qté UD',r:1,f:s=>fmt(s.qty)}],st,{empty:'Stock d’agence vide.'})}</div>`};
ACT.agDel=code=>{if(!(can('rec_ag')||can('pod')))return deny('rec_ag');const st=S.stock.filter(s=>s.qty>0&&LOC[s.loc]?.site===code&&lotOf(s.lotId).statut==='Libéré');if(!st.length)return toast('Aucun stock libéré dans cette agence.',true);
  modal('Livraison depuis l’agence',`<div class="fx"><label>Client / formation sanitaire<input id="aC" value="CSB2 – exemple"></label><label style="grid-column:1/-1">Lot à livrer<select id="aS">${st.map(s=>`<option value="${s.id}">${esc(ART[lotOf(s.lotId).art].des)} · lot ${esc(lotOf(s.lotId).lot)} · ${fmt(s.qty)} UD</option>`).join('')}</select></label><label>Quantité (UD, à l’unité possible)<input id="aQ" type="number" value="1" min="1"></label></div>`,`<button class="btn p" data-x="agDelOk" data-a="${code}">Préparer et ouvrir la POD</button>`)};
ACT.agDelOk=code=>{const s=S.stock.find(x=>x.id===$('#aS').value);const q=+$('#aQ').value;if(!(q>0)||q>s.qty)return toast('Quantité invalide.',true);s.qty-=q;const lt=lotOf(s.lotId);
  const o={no:nextNo('cmd','CMD-'),x3:'SOH-AG-'+String(S.orders.length),dest:'',destNom:$('#aC').value,sp:'AGENCE',route:'',cycle:'Hors cycle',prio:'P3',lignes:[{art:lt.art,qty:q}],statut:'En transit',ver:1,creePar:me().nom,hist:[],date:iso(today())};o.calc=colisage(o.lignes);
  S.orders.unshift(o);S.colis.push({sscc:mkSSCC(S.seq.sscc++),order:o.no,mission:'',type:q%ART[lt.art].udc?'Carton 001 – vrac':'Carton d’origine',kg:o.calc.kg,m3:o.calc.m3,contenu:[{art:lt.art,lotId:lt.id,qty:q}],statut:'Chargé'});
  audit('Livraison agence',o.no,code+' → '+o.destNom);closeModal();ACT.podNew(o.no,siteNom(code))};

/* ---------------- Rappels de lots (mock recall) ---------------- */
VIEWS.rappels=()=>ph('Rappels de lots et exercices de rappel','Traçabilité ascendante et descendante d’un lot : emplacements, quantités en stock, en transit, livrées et destinataires. Objectif contractuel : rapport complet en moins de 30 minutes (RET-002, RET-003, UAT-08, UAT-18).',`<button class="btn p" data-x="rcNew">Lancer un exercice de rappel</button>`)+
  table([{t:'N°',f:r=>`<span class="mono">${r.no}</span>`},{t:'Lot',f:r=>esc(lotOf(r.lotId).lot)+' · '+esc(ART[lotOf(r.lotId).art].des)},{t:'Type',k:'type'},{t:'Début',f:r=>frt(r.start)},{t:'Durée',f:r=>r.end?pill(fmt((r.end-r.start)/6e4,1)+' min',(r.end-r.start)<=18e5?'ok':'bad'):pill('En cours','warn')},{t:'Par',k:'by'},{t:'',f:r=>`<button class="btn s" data-x="rcOpen" data-a="${r.no}">Ouvrir</button>`}],S.recalls,{empty:'Aucun exercice. Lancez-en un sur un lot déjà livré pour voir la traçabilité aval.'});
ACT.rcNew=()=>{if(!need('recall'))return;const lots=S.lots.filter(l=>S.colis.some(c=>c.contenu.some(x=>x.lotId===l.id))).concat(S.lots.slice(0,30));const uniq=[...new Map(lots.map(l=>[l.id,l])).values()];
  modal('Lancer un rappel',`<div class="fx"><label>Lot<select id="rcL">${uniq.map(l=>`<option value="${l.id}">${esc(l.lot)} – ${esc(ART[l.art].des)}</option>`).join('')}</select></label><label>Type<select id="rcT"><option>Exercice de rappel (mock recall)</option><option>Rappel réel – blocage immédiat</option></select></label><label>Motif<input id="rcM" value="Exercice trimestriel de traçabilité"></label></div>`,`<button class="btn p" data-x="rcGo">Démarrer le chronomètre</button>`)};
ACT.rcGo=()=>{const r={no:nextNo('rcl','RCL-'),lotId:$('#rcL').value,type:$('#rcT').value,motif:$('#rcM').value,start:Date.now(),end:null,by:me().nom};S.recalls.unshift(r);
  if(r.type.startsWith('Rappel réel')){const l=lotOf(r.lotId);l.statut='Rappelé';lotUnavailable(r.lotId,'rappel '+r.no);x3('Rappel de lot','Blocage lot',l.lot,{});audit('Rappel',r.no,'Lot '+l.lot+' bloqué « Rappelé » sur tous les sites')}
  audit('Rappel',r.no,'Démarré – '+r.type);closeModal();refresh();ACT.rcOpen(r.no)};
function traceLot(id){const l=lotOf(id);const inStock=S.stock.filter(s=>s.lotId===id&&s.qty>0);const kids=S.lots.filter(x=>Array.isArray(x.parent)&&x.parent.includes(id));
  const cs=S.colis.filter(c=>c.contenu.some(x=>x.lotId===id));const out=cs.map(c=>{const o=S.orders.find(x=>x.no===c.order);const p=S.pods.find(x=>x.order===c.order);const q=sum(c.contenu.filter(x=>x.lotId===id),x=>x.qty);const pl=p?.lignes.find(x=>x.lotId===id);return {sscc:c.sscc,order:c.order,dest:o?.destNom,sp:o?.sp,mission:c.mission,statut:c.statut,qty:q,recu:pl?pl.recu:null,pod:p?.no,recep:p?p.recNom+' ('+p.fonction+')':''}});
  const trf=S.transfers.filter(t=>t.lotId===id);return {l,inStock,out,trf,kids}}
ACT.rcOpen=no=>{const r=S.recalls.find(x=>x.no===no);const t=traceLot(r.lotId);const a=ART[t.l.art];const rec=S.receipts.find(x=>x.lignes.some(y=>y.lot===t.l.lot));
  modal('Rappel '+no+' – lot '+t.l.lot,`<div class="fx"><div class="fl">Article<b>${esc(a.des)} · GTIN ${a.gtin}</b></div><div class="fl">Péremption<b>${fr(t.l.exp)}</b></div><div class="fl">Fournisseur<b>${esc(t.l.fourn)}</b></div><div class="fl">Statut<b>${lotPill(t.l.statut)}</b></div><div class="fl">Réception<b>${esc(rec?.no||t.l.recu)}</b></div><div class="fl">Chronomètre<b>${r.end?fmt((r.end-r.start)/6e4,1)+' min (clôturé)':'en cours depuis '+fmt((Date.now()-r.start)/6e4,1)+' min'}</b></div></div>
  <h3>1. En stock (entrepôts et agences)</h3>${table([{t:'Site',f:s=>siteNom(LOC[s.loc]?.site)},{t:'Emplacement',f:s=>locTag(s.loc)},{t:'Qté UD',r:1,f:s=>fmt(s.qty)},{t:'SSCC',f:s=>`<span class="mono small">${s.sscc||''}</span>`}],t.inStock,{empty:'Aucun stock restant.'})}
  <h3>2. Transferts</h3>${table([{t:'N°',k:'no'},{t:'De',k:'from'},{t:'Vers',k:'to'},{t:'Qté',r:1,f:x=>fmt(x.qty)},{t:'Statut',k:'statut'}],t.trf,{empty:'Aucun transfert.'})}
  <h3>3. Distribué (traçabilité aval)</h3>${table([{t:'SSCC',f:x=>`<span class="mono small">${x.sscc}</span>`},{t:'Commande',k:'order'},{t:'Destination',f:x=>esc(x.dest)+' <span class="small muted">'+esc(x.sp)+'</span>'},{t:'Statut',f:x=>pill(x.statut,x.statut==='Livré'?'ok':'warn')},{t:'Qté',r:1,f:x=>fmt(x.qty)},{t:'Reçu (POD)',r:1,f:x=>x.recu==null?'—':fmt(x.recu)},{t:'POD / réceptionnaire',f:x=>esc((x.pod||'')+' '+x.recep)}],t.out,{empty:'Aucune expédition de ce lot.'})}
  ${t.kids.length?`<h3>4. Lots enfants (transformations)</h3>${table([{t:'Lot',k:'lot'},{t:'Article',f:k=>esc(ART[k.art]?.des)},{t:'Péremption',f:k=>fr(k.exp)}],t.kids)}`:''}
  <div class="note">Bilan : ${fmt(sum(t.inStock,s=>s.qty))} UD localisées en stock · ${fmt(sum(t.out.filter(x=>x.statut!=='Livré'),x=>x.qty))} UD en transit · ${fmt(sum(t.out.filter(x=>x.statut==='Livré'),x=>x.recu??x.qty))} UD livrées à ${new Set(t.out.filter(x=>x.statut==='Livré').map(x=>x.dest)).size} destinataire(s).</div>`,
  (r.end?'':`<button class="btn n" data-x="rcEnd" data-a="${no}">Clôturer l’exercice</button>`)+`<button class="btn" data-x="rcPDF" data-a="${no}">Rapport PDF</button>`,{w:'1100px'})};
ACT.rcEnd=no=>{const r=S.recalls.find(x=>x.no===no);r.end=Date.now();audit('Rappel',no,'Clôturé en '+fmt((r.end-r.start)/6e4,1)+' min');closeModal();refresh()};
ACT.rcPDF=no=>{const r=S.recalls.find(x=>x.no===no);const t=traceLot(r.lotId);const a=ART[t.l.art];const d=pdfDoc('Rapport de rappel – '+no,'Lot '+t.l.lot+' · '+a.des+' · '+r.type);
  d.setFontSize(9);d.setTextColor(30);d.text('GTIN '+a.gtin+' · péremption '+fr(t.l.exp)+' · fournisseur '+t.l.fourn+' · durée '+(r.end?fmt((r.end-r.start)/6e4,1)+' min':'en cours'),14,38);
  let y=pdfTable(d,46,['Site','Emplacement','Qté UD'],t.inStock.map(s=>[siteNom(LOC[s.loc]?.site),s.loc,s.qty]),[70,80,30]);
  y=pdfTable(d,y+6,['SSCC','Commande','Destination','Statut','Qté','Reçu','POD'],t.out.map(x=>[x.sscc,x.order,x.dest,x.statut,x.qty,x.recu??'',x.pod||'']),[38,24,40,18,14,14,38]);d.__foot();saveFile('Rapport_rappel_'+no+'.pdf',d.output('arraybuffer'),'application/pdf')};

/* ---------------- Journal d'audit ---------------- */
VIEWS.audit=()=>ph('Journal d’audit','Toute création, modification, approbation, export et décision est horodatée et attribuée (ADM-003, ADM-004).',`<button class="btn" data-x="xlsAudit">Exporter (Excel)</button>`)+table([{t:'Date',f:a=>frt(a.ts)},{t:'Utilisateur',f:a=>esc(a.user)+'<br><span class="small muted">'+esc(a.role)+'</span>'},{t:'Action',k:'action'},{t:'Objet',k:'objet'},{t:'Détail',k:'detail'}],S.audit,{max:700});
ACT.xlsAudit=()=>xlsxExport('SALAMA_WMS_Audit_'+iso(today()),[['Audit',S.audit.map(a=>({Date:frt(a.ts),Utilisateur:a.user,Rôle:a.role,Action:a.action,Objet:a.objet,Détail:a.detail}))]]);

/* ---------------- Volumes, espaces et CBM ---------------- */
let spaceP={inW:120,outC:2380,trS:0,weeks:20};
VIEWS.espace=()=>{const W=spaceP.weeks;const labels=[];const s1=[];let occ=REF.sites[0].occRef;const c1=new Date(REF.cycles[0].dep);
  for(let w=0;w<W;w++){const d=addD(today(),w*7);labels.push(fr(d).slice(0,5));occ+=spaceP.inW-spaceP.trS;REF.cycles.forEach(c=>{const dep=new Date(c.dep);if(dep>=d&&dep<addD(d,7))occ-=spaceP.outC});s1.push(Math.max(0,occ))}
  const cap=REF.sites[0].cap;const routes=Object.keys(REF.routes).map(r=>{const os=S.orders.filter(o=>o.route===r&&o.cycle==='C1');return {r,n:os.length,m3:sum(os,o=>o.calc.m3),kg:sum(os,o=>o.calc.kg),colis:sum(os,o=>o.calc.colis)}});
  return ph('Volumes, espaces et CBM','Occupation par site, prévision de l’espace de SALAMA 1 semaine par semaine, volumes par route et calculateur CBM poids-volume.')+
  `<div class="grid g2"><div class="card"><h2>Occupation de référence et besoin</h2>${table([{t:'Site',k:'nom'},{t:'Capacité',r:1,f:s=>fmt(s.cap)},{t:'Occupation',r:1,f:s=>fmt(s.occRef)},{t:'Taux',r:1,f:s=>pct(s.occRef/s.cap,1)},{t:'Positions à libérer ou créer pour 85 %',r:1,f:s=>fmt(Math.max(0,s.occRef-s.cap*.85))}],REF.sites)}<p class="small muted">Réseau : ${fmt(sum(REF.sites,s=>s.cap))} palettes de capacité, ${fmt(sum(REF.sites,s=>s.occRef))} occupées (${pct(sum(REF.sites,s=>s.occRef)/sum(REF.sites,s=>s.cap),1)}) – source : base logistique consolidée 2026.</p></div>
  <div class="card"><h2>Hypothèses de prévision (SALAMA 1)</h2><div class="fx"><label>Entrées (palettes / semaine)<input id="spI" type="number" value="${spaceP.inW}"></label><label>Sorties par départ de cycle (palettes)<input id="spO" type="number" value="${spaceP.outC}"></label><label>Transferts vers S2 / S3 (palettes / semaine)<input id="spT" type="number" value="${spaceP.trS}"></label><label>Horizon (semaines)<input id="spW" type="number" value="${W}" min="4" max="52"></label></div><p class="small muted">Valeurs par défaut indicatives à remplacer par les données SALAMA : environ 3 426 m³ par cycle (plan V11) convertis en palettes de 1,44 m³ remplies à 85 %, réparties entre les trois sites.</p></div></div>
  <div class="card"><h2>Prévision d’occupation – SALAMA 1 (palettes)</h2>${svgLine([{n:'Occupation prévue',v:s1,c:'var(--blue)'}],labels,{refs:[{v:cap,l:'Capacité '+fmt(cap),c:'var(--red)'},{v:cap*.85,l:'Cible 85 %',c:'var(--green)'}],label:'Prévision occupation'})}</div>
  <div class="grid g2"><div class="card"><h2>Volumes C1 par route (commandes saisies)</h2>${table([{t:'Route',f:r=>r.r+' – '+esc(REF.routes[r.r])},{t:'Cmd',r:1,k:'n'},{t:'Colis',r:1,f:r=>fmt(r.colis)},{t:'kg',r:1,f:r=>fmt(r.kg)},{t:'m³',r:1,f:r=>fmt(r.m3,2)}],routes)}</div>
  <div class="card"><h2>Calculateur CBM poids-volume</h2><div class="fx"><label>Longueur (cm)<input id="cbL" type="number" value="54"></label><label>Largeur (cm)<input id="cbW" type="number" value="40"></label><label>Hauteur (cm)<input id="cbH" type="number" value="35"></label><label>Poids par colis (kg)<input id="cbK" type="number" value="12"></label><label>Nombre de colis<input id="cbN" type="number" value="300"></label><label>Classe de route<select id="cbR">${opt(SP.map(s=>[s.code,s.code+' – '+s.veh]))}</select></label></div><div id="cbOut" style="margin-top:10px"></div></div></div>`};
BIND.espace=()=>{[['spI','inW'],['spO','outC'],['spT','trS'],['spW','weeks']].forEach(([i,k])=>$('#'+i).onchange=e=>{spaceP[k]=+e.target.value||0;refresh()});
  const cb=()=>{const v=cm3(+$('#cbL').value,+$('#cbW').value,+$('#cbH').value);const n=+$('#cbN').value,kg=+$('#cbK').value*n,m3=v*n;const sp=SP.find(s=>s.code===$('#cbR').value);const ve=choixVehicule(m3,kg,sp);const vk=m3*1e6/5000;
    $('#cbOut').innerHTML=`<div class="kpis"><div class="kpi k-info"><b>${fmt(v,4)}</b><span>m³ par colis</span></div><div class="kpi k-info"><b>${fmt(m3,2)}</b><span>m³ total (CBM)</span></div><div class="kpi k-info"><b>${fmt(kg)}</b><span>kg réels · ${fmt(vk)} kg volumétriques (1:5000)</span></div><div class="kpi k-info"><b>${fmt(m3/(1.44*.85),1)}</b><span>palettes 120×80×150 à 85 %</span></div><div class="kpi ${ve.statut==='PLEIN'?'k-ok':ve.statut==='MUTUALISER'?'k-bad':'k-warn'}"><b>${ve.n} × ${esc(ve.code)}</b><span>${esc(ve.lib)} · ${pct(ve.fill)}</span></div></div>`};
  ['cbL','cbW','cbH','cbK','cbN','cbR'].forEach(i=>$('#'+i).oninput=cb);cb()};

/* ---------------- Classement ABC ---------------- */
VIEWS.abc=()=>{computeABC();const arts=S.articles.slice().sort((a,b)=>(b.abcVal||0)-(a.abcVal||0));const tot=sum(arts,a=>a.abcVal||0);let cum=0;
  const mis=S.stock.filter(s=>s.qty>0&&LOC[s.loc]?.site===S.site&&['R','SOL'].includes(LOC[s.loc].zone)&&ART[lotOf(s.lotId).art].abc==='A'&&LOC[s.loc].abc==='C');
  return ph('Classement ABC et re-slotting','Pareto sur la valeur des sorties : A ≈ 80 %, B ≈ 15 %, C ≈ 5 %. Les articles A doivent occuper les emplacements A (près des quais et du picking) ; le WMS propose les transferts de re-slotting (PUT-004).')+
  `<div class="grid g2"><div class="card"><h2>Pareto</h2>${table([{t:'Article',f:a=>esc(a.des)},{t:'Valeur (M MGA)',r:1,f:a=>fmt((a.abcVal||0)/1e6,1)},{t:'Cumul',r:1,f:a=>{cum+=a.abcVal||0;return pct(cum/tot,1)}},{t:'Classe',f:a=>pill(a.abc,a.abc==='A'?'ok':a.abc==='B'?'info':'neu')}],arts,{max:520})}</div>
  <div class="card"><h2>Propositions de re-slotting (${esc(siteNom(S.site))})</h2>${table([{t:'Article',f:s=>esc(ART[lotOf(s.lotId).art].des)},{t:'Actuel',f:s=>locTag(s.loc)},{t:'Proposé',f:s=>{const L=S.locations.find(l=>l.site===S.site&&l.zone===LOC[s.loc].zone&&l.abc==='A'&&occLoc(l.code)===0);return L?locTag(L.code):'—'}},{t:'',f:s=>{const L=S.locations.find(l=>l.site===S.site&&l.zone===LOC[s.loc].zone&&l.abc==='A'&&occLoc(l.code)===0);return L?`<button class="btn s p" data-x="trfNew" data-a="${s.id}" data-b="${L.code}">Créer le transfert</button>`:''}}],mis,{empty:'Aucun article A mal placé sur ce site.'})}</div></div>`};

/* ---------------- Catalogue articles ---------------- */
VIEWS.articles=()=>ph('Catalogue articles (données maîtres)','Fiche article unique : code, code X3, GTIN, unité de distribution, hiérarchie unité – carton, dimensions et poids, température, programme, durée résiduelle minimale. Toute création ou modification suit un circuit à deux personnes (MDM-001 à MDM-006).',`<button class="btn" data-x="xlsArt">Exporter (Excel)</button>`)+
  `<div class="note w">Catalogue de démonstration (28 articles fictifs). Le catalogue réel des dimensions (outil de planification poids-volume-camions) sera chargé à la reprise de données.</div>`+
  table([{t:'Code / X3',f:a=>`<b class="mono">${a.code}</b><br><span class="small muted">${a.x3}</span>`},{t:'Désignation',f:a=>esc(a.des)+'<br><span class="small muted">'+esc(a.ud)+'</span>'},{t:'GTIN',f:a=>`<span class="mono small">${a.gtin}</span>`},{t:'Prog.',k:'prog'},{t:'Temp. / transport',f:a=>esc(a.temp)+'<br><span class="small muted">'+esc(a.tr)+'</span>'},{t:'Carton (cm)',f:a=>`${a.cl}×${a.cw}×${a.ch}<br><span class="small muted">${fmt(a.ckg,1)} kg · ${fmt(cm3(a.cl,a.cw,a.ch),4)} m³</span>`},{t:'UD / carton',r:1,f:a=>fmt(a.udc)},{t:'UD (cm, kg)',f:a=>`${a.ul}×${a.uw}×${a.uh}<br><span class="small muted">${fmt(a.ukg,3)} kg</span>`},{t:'Rés. min.',r:1,f:a=>a.minRes+' mois'},{t:'ABC',f:a=>pill(a.abc||'-',a.abc==='A'?'ok':'neu')},{t:'',f:a=>`<button class="btn s" data-x="artEdit" data-a="${a.code}">Modifier</button>`}],S.articles,{max:680});
ACT.xlsArt=()=>xlsxExport('SALAMA_WMS_Catalogue_'+iso(today()),[['Articles',S.articles.map(a=>({Code:a.code,X3:a.x3,GTIN:a.gtin,Désignation:a.des,UD:a.ud,Catégorie:a.cat,Programme:a.prog,Température:a.temp,Transport:a.tr,'Carton L cm':a.cl,'Carton l cm':a.cw,'Carton H cm':a.ch,'Carton kg':a.ckg,'UD/carton':a.udc,'UD L':a.ul,'UD l':a.uw,'UD H':a.uh,'UD kg':a.ukg,'Prix MGA':a.prix,'Durée résiduelle min (mois)':a.minRes,ABC:a.abc}))]]);
ACT.artEdit=code=>{if(!(can('admin')||can('qa')||can('trf_ok')))return deny('admin');const a=ART[code];
  modal('Modifier '+code,`<div class="fx">${[['cl','Carton L (cm)'],['cw','Carton l (cm)'],['ch','Carton H (cm)'],['ckg','Carton (kg)'],['udc','UD par carton'],['minRes','Durée résiduelle min. (mois)']].map(([k,l])=>`<label>${l}<input id="ae_${k}" type="number" step="any" value="${a[k]}"></label>`).join('')}<label>GTIN<input id="ae_gtin" class="mono" value="${a.gtin}"></label></div><div class="note small">Maker – checker : la modification est enregistrée en attente et doit être approuvée par un second profil habilité avant activation.</div>`,`<button class="btn p" data-x="artSave" data-a="${code}">Soumettre la modification</button>`)};
ACT.artSave=code=>{const g=$('#ae_gtin').value.trim();if(g.length!==14||gtinCheck(g.slice(0,13))!=g[13])return toast('GTIN invalide (14 chiffres, clé de contrôle) – MDM-006.',true);
  const ch={};['cl','cw','ch','ckg','udc','minRes'].forEach(k=>ch[k]=+$('#ae_'+k).value);ch.gtin=g;const a=ART[code];a.pending={ch,by:me().nom,byId:me().id};audit('Données maîtres',code,'Modification soumise : '+JSON.stringify(ch));closeModal();toast('Modification en attente d’approbation (voir À propos › Approbations).');refresh()};

/* ---------------- Réseau et flotte ---------------- */
let netTab='sp';
VIEWS.reseau=()=>ph('Réseau de distribution et flotte','Référentiels issus du plan de distribution cyclique 2027 (V11) et de l’outil intégré de planification (V4.5) : 10 routes, 44 sous-parcours, '+DEST.length+' arrêts, 5 agences, flotte interne documentée et gabarits 3PL.')+
  `<div class="tabs">${[['sp','Routes et sous-parcours'],['dest','Arrêts'],['fleet','Flotte interne'],['3pl','Transporteurs et gabarits 3PL'],['sites','Sites et agences']].map(([k,l])=>`<button class="${netTab===k?'on':''}" data-x="netTab" data-a="${k}">${l}</button>`).join('')}</div>`+
  (netTab==='sp'?table([{t:'Code',k:'code'},{t:'Route',f:s=>s.route+' – '+esc(REF.routes[s.route])},{t:'Sous-parcours',k:'nom'},{t:'Séquence de livraison',f:s=>esc(s.seq.join(' → '))},{t:'Km max.',r:1,f:s=>fmt(s.km)},{t:'Durée (j)',r:1,f:s=>fmt(s.j,1)},{t:'Véhicule recommandé',k:'veh'}],SP,{max:700}):
   netTab==='dest'?table([{t:'Code',k:'code'},{t:'Arrêt',k:'nom'},{t:'Sous-parcours',k:'sp'},{t:'Ordre',r:1,k:'ordre'}],DEST,{max:700}):
   netTab==='fleet'?table([{t:'Type',k:'type'},{t:'Modèle',k:'mod'},{t:'Immatriculation',f:f=>`<span class="mono">${esc(f.imm)}</span>`},{t:'Charge utile (t)',r:1,f:f=>fmt(f.t,2)},{t:'Volume (m³)',r:1,k:'m3'},{t:'État',f:f=>pill(f.etat,f.etat==='BON'?'ok':'warn')}],FLEET,{max:700}):
   netTab==='3pl'?table([{t:'Gabarit',k:'lib'},{t:'Tonnage max.',r:1,f:v=>fmt(v.t,1)+' t'},{t:'Volume max.',r:1,f:v=>v.m3+' m³'}],REF.vclasses)+table([{t:'Transporteur',k:'nom'},{t:'Adresse',k:'adr'},{t:'Téléphone',k:'tel'},{t:'Lot',k:'lot'}],S.transporteurs):
   table([{t:'Code',k:'code'},{t:'Nom',k:'nom'},{t:'Capacité (pal.)',r:1,f:s=>s.cap?fmt(s.cap):'—'},{t:'Racks',f:s=>s.racks===undefined?'—':s.racks?'Oui':'Non – stockage au sol'},{t:'Chaîne du froid',f:s=>s.froid===undefined?'—':s.froid?'Oui':'Non'},{t:'Emplacements modélisés',r:1,f:s=>fmt(S.locations.filter(l=>l.site===s.code).length)}],REF.sites.concat(REF.agences)));
ACT.netTab=k=>{netTab=k;refresh()};

/* ---------------- Rôles et séparation des tâches ---------------- */
VIEWS.roles=()=>{const perms=Object.keys(PERM_LIB);
  return ph('Rôles, habilitations et séparation des tâches','Principe du moindre privilège : chaque profil n’a que les droits de sa fonction. Les incompatibilités ci-dessous sont bloquées par le système, pas seulement par procédure (QLT-002, VAL-004, ADM-001).')+
  `<div class="card"><h2>Incompatibilités contrôlées</h2>${table([{t:'Tâche 1',f:r=>r[0]},{t:'Tâche 2',f:r=>r[1]},{t:'Règle appliquée',f:r=>r[2]}],SOD)}</div>`+
  `<div class="card"><h2>Matrice des droits</h2><div class="tw"><table><thead><tr><th>Profil</th>${perms.map(p=>`<th style="writing-mode:vertical-rl;transform:rotate(180deg);font-size:.72rem">${esc(PERM_LIB[p])}</th>`).join('')}</tr></thead><tbody>${Object.entries(ROLES).map(([k,r])=>`<tr><td><b>${esc(r.n)}</b></td>${perms.map(p=>`<td style="text-align:center">${r.p.includes(p)?'<span style="color:var(--green)">●</span>':''}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`+
  `<div class="card"><h2>Utilisateurs de démonstration</h2>${table([{t:'Nom',k:'nom'},{t:'Profil',f:u=>esc(ROLES[u.role].n)},{t:'Site',k:'site'},{t:'PIN de démonstration',f:u=>`<span class="mono">${u.pin}</span>`},{t:'',f:u=>u.id===S.cur?pill('Actif','ok'):`<button class="btn s" data-x="setUser" data-a="${u.id}">Utiliser ce profil</button>`}],S.users)}<p class="small muted">En production : comptes nominatifs, authentification unique (SSO) et double authentification pour les administrateurs ; aucun PIN affiché.</p></div>`};
ACT.setUser=id=>{S.cur=id;$('#userSel').value=id;save();toast('Profil actif : '+me().nom);refresh()};

/* ---------------- Interface Sage X3 ---------------- */
const X3MAP=[['Articles et hiérarchies','X3 → WMS','ITM (articles), unités, GTIN','≤ 15 min après approbation'],['Partenaires et sites','X3 → WMS','BPC / BPS, adresses, GLN','≤ 1 h'],['Commandes d’achat / ASN','X3 → WMS','POH','≤ 5 min'],['Réception confirmée','WMS → X3','PTH (réception), lots, écarts','≤ 5 min'],['Commandes clients validées','X3 ↔ WMS','SOH (version, priorité, lignes)','≤ 5 min'],['Expédition','WMS → X3','SDH (livraison), lots, SSCC, véhicule','≤ 5 min'],['POD et écarts','WMS → X3','Quantités acceptées → facture SIH / avoir','≤ 15 min après synchronisation'],['Facture et paiement','X3 → WMS','Statut proforma, facture, payé, reste dû','≤ 15 min'],['Ajustements, destructions','WMS ↔ X3','Mouvements divers / régularisations, motif, valeur','≤ 15 min'],['Transferts inter-sites','WMS ↔ X3','Transferts de stock entre dépôts','≤ 5 min'],['Stock et réconciliation','WMS → X3 / BI','Article, lot, site, statut','Horaire + clôture quotidienne']];
VIEWS.x3=()=>ph('Interface Sage X3','Sage X3 reste le système de référence pour la finance, les achats, les ventes et le stock comptable ; le WMS pilote les mouvements physiques. Échanges idempotents, horodatés, rejouables ; aucun message perdu silencieusement (§9).',
  `<button class="btn ${S.x3down?'p':'d'}" data-x="x3Toggle">${S.x3down?'Rétablir la connexion X3':'Simuler une indisponibilité X3'}</button><button class="btn" data-x="x3Replay">Rejouer la file</button><button class="btn" data-x="x3Dup">Simuler un double envoi</button><button class="btn" data-x="offToggle">${S.offline?'Quitter le mode dégradé':'Simuler le mode dégradé'}</button>`)+
  `<div class="note w">Connecteur simulé dans ce démonstrateur. Les objets et services web X3 (SOAP ou REST selon la version installée), le dossier, les transactions de saisie et le modèle de licence sont à confirmer avec la DSI de SALAMA avant développement.</div>`+
  `<div class="card"><h2>Catalogue des flux</h2>${table([{t:'Flux',f:r=>r[0]},{t:'Sens',f:r=>r[1]},{t:'Objet / données X3',f:r=>r[2]},{t:'Latence cible',f:r=>r[3]}],X3MAP)}</div>`+
  `<div class="card"><h2>Journal des messages</h2>${table([{t:'Date',f:m=>frt(m.ts)},{t:'Flux',k:'flux'},{t:'Objet',k:'objet'},{t:'Référence',f:m=>`<span class="mono small">${esc(m.ref)}</span>`},{t:'Statut',f:m=>pill(m.statut,m.statut==='Accusé'?'ok':m.statut==='Rejeté'?'bad':m.statut==='Doublon ignoré'?'neu':'warn')+(m.horsLigne?' '+pill('saisi hors ligne','warn'):'')},{t:'Essais',r:1,k:'essais'}],S.x3msg,{max:520})}</div>`;
ACT.x3Toggle=()=>{if(!need('admin'))return;S.x3down=!S.x3down;audit('Interface X3','Connexion',S.x3down?'Indisponibilité simulée':'Rétablie');refresh()};
ACT.offToggle=()=>{S.offline=!S.offline;audit('Mode dégradé','Réseau',S.offline?'Activé : scans conservés localement':'Réseau rétabli');refresh()};
ACT.x3Replay=()=>{if(!(can('x3')||can('admin')))return deny('x3');if(S.x3down)return toast('X3 toujours indisponible : la file est conservée.',true);let n=0;S.x3msg.forEach(m=>{if(m.statut!=='Accusé'){m.statut='Accusé';m.essais++;n++}});audit('Interface X3','File',n+' message(s) rejoué(s) sans doublon');toast(n+' message(s) rejoué(s).');refresh()};

/* ---------------- Formation et à propos ---------------- */
const MODS=[['Réception et quarantaine','Module 01 – induction personnel temporaire'],['Libération pharmaceutique','SOP qualité – à produire'],['Mise en emplacement et adressage','Module caristes – conducteurs d’engins'],['Inventaire simplifié','Formation inventaire animée V4'],['Préparation FEFO','Module préparateurs (pickers)'],['Contrôle et emballage','Module contrôleurs – emballeurs'],['Mesure des cartons et planification des camions','Vidéo V5 et tutoriel de l’outil V3'],['Plan de distribution 2027','Vidéo de formation V7'],['Chauffeurs et POD','Module chauffeurs – convoyeurs'],['Rappels de lots','À produire']];
VIEWS.formation=()=>ph('Modules de formation','Un emplacement par module du WMS. Les vidéos de formation SALAMA existantes y seront intégrées après validation, avec un quiz par chapitre.')+`<div class="grid g3">${MODS.map(([m,v],i)=>`<div class="card"><h3>${String(i+1).padStart(2,'0')} · ${esc(m)}</h3><p class="small muted">Support existant ou prévu : ${esc(v)}</p>${pill('Vidéo à intégrer','warn')}</div>`).join('')}</div>`;
VIEWS.apropos=()=>{const pend=S.articles.filter(a=>a.pending);
  return ph('À propos du démonstrateur','Prototype fonctionnel destiné à illustrer, tester et valider avec les équipes SALAMA les processus du futur WMS avant l’appel d’offres. Il ne remplace ni la solution qui sera retenue, ni les validations de la Direction.')+
  `<div class="grid g2"><div class="card"><h2>Ce qui est couvert</h2><ul class="small"><li>Référentiels articles, emplacements adressés jusqu’à la case avec QR et GLN, sites, agences, 44 sous-parcours, flotte.</li><li>Réception par scan GS1, contrôle de durée résiduelle, SSCC, quarantaine, libération pharmaceutique signée.</li><li>Mise en emplacement guidée, stock par lot, FEFO bloquant, alertes 12 / 9 / 6 / 3 mois, transferts, inventaires à l’aveugle à double validation.</li><li>Transformation et recomposition avec nouvelle identité et filiation des lots.</li><li>Commandes à commande unique, validation DVM / DAS gelée, calcul poids-volume-colis dès la saisie, cartons 001 / 003 / 007, plus petite unité de distribution.</li><li>Plan 2027 : J-20, stop / go J-15, choix et remplissage des camions, préparation, contrôle, colisage, chargement inverse, POD signée avec QR, restes à livrer, clôture.</li><li>Rappels avec chronomètre, ABC et re-slotting, prévision d’espace, CBM, journal d’audit, file X3 rejouable, mode dégradé.</li></ul></div>
  <div class="card"><h2>Points à confirmer avant production</h2><ul class="small"><li>Services web et objets Sage X3 disponibles, dossier, licence (DSI).</li><li>Préfixe GS1 de SALAMA (le préfixe affiché est l’exemple officiel GS1).</li><li>Nombre réel d’emplacements par site, plan d’adressage et étiquetage.</li><li>Dates de C2 à C4 ; liste et effectifs des cinq agences.</li><li>Valeur juridique de la signature électronique sur la POD (cadre malgache).</li><li>Hébergement, sauvegarde et protection des données ; propriété des données à SALAMA.</li></ul></div></div>
  <div class="card"><h2>Approbations de données maîtres en attente</h2>${table([{t:'Article',f:a=>esc(a.code+' – '+a.des)},{t:'Proposé par',f:a=>esc(a.pending.by)},{t:'Changements',f:a=>`<span class="small mono">${esc(JSON.stringify(a.pending.ch))}</span>`},{t:'',f:a=>`<button class="btn s p" data-x="artApp" data-a="${a.code}">Approuver</button>`}],pend,{empty:'Aucune modification en attente.'})}</div>
  <div class="card"><h2>Données</h2><div class="row"><button class="btn" data-x="dataExport">Exporter la base (JSON)</button><label class="btn">Importer une base (JSON)<input type="file" id="impF" accept=".json" hidden></label><button class="btn d" data-x="dataReset">Réinitialiser la démonstration</button><button class="btn" data-x="theme">Basculer clair / sombre</button></div><p class="small muted">Les données sont conservées dans ce navigateur uniquement. En production, elles seront centralisées sur le serveur SALAMA (base PostgreSQL, sauvegardes chiffrées), avec un serveur local de secours par entrepôt.</p></div>
  <div class="card row"><img src="${LOGO_J}" alt="JPN Management Consulting" style="height:54px"><div class="small">Conception et développement : <b>JPN Management Consulting</b> · contact@jpnconsultant.com · www.jpnconsultant.com<br>© 2026 JPN Management Consulting – Tous droits réservés. Client : SALAMA – Centrale d’Achats de Médicaments Essentiels et de Matériel Médical de Madagascar. Version ${APP_REL}.</div></div>`};
BIND.apropos=()=>{const f=$('#impF');if(f)f.onchange=e=>{const file=e.target.files[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const s=JSON.parse(r.result);if(!s.articles||!s.locations)throw 0;S=s;indexes();save();toast('Base importée.');render()}catch(err){toast('Fichier JSON non reconnu.',true)}};r.readAsText(file)}};
ACT.artApp=code=>{const a=ART[code];if(!(can('qa')||can('trf_ok')||can('admin')))return deny('qa');if(a.pending.byId===me().id)return toast('Séparation des tâches : approbation par un second profil (MDM-005).',true);Object.assign(a,a.pending.ch);audit('Données maîtres',code,'Modification approuvée');delete a.pending;x3('Articles et hiérarchies','Mise à jour article',code,{});refresh()};
ACT.dataExport=()=>saveFile('SALAMA_WMS_base_'+iso(today())+'.json',JSON.stringify(S,null,1),'application/json');
ACT.dataReset=()=>{modal('Réinitialiser la démonstration','<p>Toutes les saisies de ce navigateur seront remplacées par le jeu de données de démonstration.</p>','<button class="btn d" data-x="dataResetOk">Réinitialiser</button>')};
ACT.dataResetOk=()=>{genDemo();ensureHR();scanCfg();ensureExt();ensureV14();save();closeModal();render();toast('Démonstration réinitialisée.')};
ACT.theme=()=>{const r=document.documentElement;const cur=r.dataset.theme||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');r.dataset.theme=cur==='dark'?'light':'dark';try{localStorage.setItem('salama_wms_theme',r.dataset.theme)}catch(e){}};

/* ---------------- Scan global ---------------- */
function globalScan(v){const r=parseGS1(v);if(!r)return;
  if(r.type==='loc'){if(LOC[r.loc])return ACT.locInfo(r.loc);return toast('Adresse inconnue : '+r.loc,true)}
  if(r.sscc){const c=S.colis.find(x=>x.sscc===r.sscc);const s=S.stock.find(x=>x.sscc===r.sscc);if(c)return modal('Colis '+r.sscc,`<p>${esc(c.type)} · commande ${c.order} · ${pill(c.statut,'info')}</p>`+table([{t:'Article',f:x=>esc(ART[x.art].des)},{t:'Lot',f:x=>esc(lotOf(x.lotId).lot)},{t:'Qté',r:1,f:x=>fmt(x.qty)}],c.contenu));if(s)return ACT.locInfo(s.loc);return toast('SSCC inconnu.',true)}
  if(r.gtin){const a=S.articles.find(x=>x.gtin===r.gtin);if(!a)return toast('GTIN inconnu du catalogue'+(r.erreurs.length?' ('+r.erreurs.join(', ')+')':'')+'.',true);
    const lots=S.lots.filter(l=>l.art===a.code&&(!r.lot||l.lot===r.lot));return modal(a.des,`<p>GTIN ${a.gtin} · ${esc(a.ud)}</p>`+table([{t:'Lot',k:'lot'},{t:'Péremption',f:l=>expPill(l.exp)},{t:'Statut',f:l=>lotPill(l.statut)},{t:'Stock',f:l=>stockOfLot(l.id).map(s=>locTag(s.loc)+' '+fmt(s.qty)).join('<br>')}],lots))}
  const q=String(v).trim().toUpperCase();const o=S.orders.find(x=>x.no===q||x.x3===q);if(o)return ACT.ordView(o.no);const l=S.lots.find(x=>x.lot.toUpperCase()===q);if(l){S.site=LOC[stockOfLot(l.id)[0]?.loc]?.site||S.site;stF={q:l.lot,z:'',st:'',exp:''};location.hash='#stock';return}
  toast('Aucun résultat pour « '+v+' ».',true)}

/* ---------------- Démarrage ---------------- */
function boot(){try{const t=localStorage.getItem('salama_wms_theme');if(t)document.documentElement.dataset.theme=t}catch(e){}
  S=load();if(!S)genDemo();indexes();ensureHR();scanCfg();ensureExt();ensureV14();VIEW=(location.hash||'#dash').slice(1);shell();render();initDownloads()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else setTimeout(boot,0);
